window.COURSES=[{"id": "u1", "t": "Le basi", "d": "Tipi di chitarra e parti dello strumento", "c": "#1f5a43", "lessons": [{"id": "u1l1", "t": "Le quattro famiglie", "cards": [["Classica", "Corde di nylon, manico largo e piatto (circa 52 mm al capotasto), suono morbido. È la chitarra delle scuole e del conservatorio. Paletta forata, quasi sempre senza truss rod.", ["d:cla_front", "d:cla_head"]], ["Acustica (folk)", "Corde d'acciaio, manico più stretto (circa 43 mm), suono brillante e potente. Si suona con il plettro o in fingerstyle. Ha sempre il truss rod.", ["d:d_front"]], ["Elettrica", "Non ha cassa armonica: il suono nasce dai pickup e va per forza amplificato. Il carattere dipende soprattutto da pickup, ponte e forma.", ["d:strat_front"]], ["Semiacustica e hollow body", "Elettriche con la cassa in tutto o in parte cava (fori a \"f\"). Suono caldo e arioso: jazz, blues, rockabilly.", ["d:es_body"]], ["Elettrificata", "Un'acustica o una classica con pickup e preamplificatore: suona da sola come una normale chitarra, ma si può anche collegare a un amplificatore. Sul sito sono le \"amplificate\" o \"elettroacustiche\".", ["52087"]]], "ex": {"s": "all"}, "quiz": [["Quale chitarra ha le corde in nylon?", ["Acustica folk", "Classica", "Elettrica", "Semiacustica"], 1, "Le classiche hanno corde in nylon e manico largo; le folk hanno corde d'acciaio.", "d:cla_front"], ["Un cliente vuole una chitarra che suoni da sola ma anche collegata all'impianto. Cosa gli proponi?", ["Un'elettrica solid body", "Un'acustica elettrificata", "Una classica non amplificata", "Un kit elettrico"], 1, "L'elettrificata è un'acustica vera con pickup e preamp: va bene sia in acustico sia amplificata.", "52087"], ["Quanto è largo circa il manico di una classica al capotasto?", ["43 mm", "38 mm", "52 mm", "60 mm"], 2, "Circa 52 mm: per questo chi viene dall'acustica la trova larga.", "d:cla_front"], ["Che cosa caratterizza una semiacustica?", ["Corde in nylon", "Cassa in parte cava con fori a f", "Nessun pickup", "Dodici corde"], 1, "La cassa (in parte) cava aggiunge calore; i fori a \"f\" la rendono riconoscibile.", "d:es_body"], ["Perché su una classica non devi montare corde d'acciaio?", ["Suonano troppo piano", "Non è costruita per quel tiro e si danneggia", "Non entrano nel ponte", "Non si accordano"], 1, "Le classiche spesso non hanno truss rod: il tiro delle corde d'acciaio rovina manico e ponte.", "d:cla_front"]]}, {"id": "u1l2", "t": "Le parti della chitarra", "cards": [["Paletta e meccaniche", "In cima al manico: le meccaniche tendono le corde. \"Bloccanti\" (locking) vuol dire che stringono la corda da sole: cambio rapido e accordatura stabile.", ["d:strat_head"]], ["Capotasto", "Il pezzetto di osso, plastica o grafite con le scanalature: decide l'altezza delle corde nei primi tasti. La sua larghezza si misura in mm e dice quanto è largo il manico.", ["d:d_head"]], ["Manico e truss rod", "Il manico può essere avvitato (bolt-on, tipico Fender), incollato (set-neck, tipico Gibson) o passante (neck-through). Dentro c'è il truss rod, la barra che regola la curvatura.", ["d:lp_head"]], ["Tastiera, tasti, raggio", "La tastiera è il legno sopra il manico; i tasti sono le barrette metalliche. Il raggio è la curvatura della tastiera: più è piatta (12\"–16\"), più sono facili i bending.", ["d:fretboard"]], ["Corpo, ponte, pickup", "Il ponte ancora le corde al corpo e regola altezza e intonazione. I pickup sono i \"microfoni\" magnetici delle elettriche.", ["d:strat_body"]], ["Il diapason (scala)", "È la lunghezza vibrante della corda. Fender 25,5\" (648 mm), Gibson 24,75\" (628 mm), PRS 25\" (635 mm), classica 650 mm. Scala lunga = corde più tese e suono più netto.", ["196615", "194941"]]], "quiz": [["Che cos'è il truss rod?", ["Una corda di ricambio", "La barra dentro al manico che ne regola la curvatura", "Il pezzo che regge le corde sul ponte", "Un tipo di pickup"], 1, "Il truss rod contrasta il tiro delle corde e regola la curvatura del manico.", "d:lp_head"], ["Manico avvitato si dice…", ["Set-neck", "Neck-through", "Bolt-on", "Headless"], 2, "Bolt-on = avvitato (Fender); set-neck = incollato (Gibson); neck-through = passante.", "202901"], ["Qual è la scala tipica Fender?", ["24,75\" (628 mm)", "25\" (635 mm)", "25,5\" (648 mm)", "650 mm"], 2, "25,5\" è la scala Fender; 24,75\" è Gibson; 25\" è PRS.", "196615"], ["Cosa significano meccaniche \"locking\"?", ["Meccaniche dorate", "Meccaniche che bloccano la corda: cambio rapido e accordatura stabile", "Meccaniche per mancini", "Meccaniche senza ingranaggi"], 1, "Le meccaniche bloccanti serrano la corda e riducono gli scivolamenti.", "d:strat_head"], ["Una tastiera con raggio 16\" è…", ["Molto curva", "Quasi piatta, comoda per i bending", "Senza tasti", "Solo per classiche"], 1, "Raggio grande = tastiera più piatta. Il 7,25\" vintage è molto curvo.", "d:strat_body"]]}]}, {"id": "u2", "t": "Le forme elettriche", "d": "Riconoscere a colpo d'occhio i modelli storici", "c": "#8a4b1f", "lessons": [{"id": "u2l1", "t": "Fender: Strat e Tele", "cards": [["Telecaster (1950)", "La prima elettrica solid body di serie. Spalla singola, due single coil, ponte fisso a piastra. Suono secco e tagliente: country, indie, rock essenziale.", ["d:tele_body"]], ["Stratocaster (1954)", "L'elettrica più copiata al mondo: doppia spalla mancante, tre single coil, selettore a 5 posizioni, leva del vibrato. Va bene per quasi tutto.", ["d:strat_front"]], ["Jazzmaster e Mustang", "La Jazzmaster ha corpo asimmetrico e pickup larghi dal suono morbido (surf, indie). La Mustang ha la scala corta (24\"): piccola e graffiante.", ["192282", "169419"]], ["Come si leggono i nomi Fender", "\"mn\" = tastiera in acero (maple), \"rw\" = palissandro (rosewood), \"pf\" = pau ferro, \"lrl\" = alloro (laurel). \"SSS/HSS\" indica i pickup. Es: \"Player II Stratocaster HSS rw\".", ["202901", "198357"]]], "ex": {"fa": ["Stratocaster", "Telecaster"]}, "quiz": [["Qual è la prima elettrica solid body di serie?", ["Stratocaster", "Les Paul", "Telecaster", "SG"], 2, "La Telecaster nasce nel 1950 (prima si chiamava Broadcaster).", "d:tele_body"], ["Quanti pickup ha una Stratocaster classica?", ["Uno", "Due", "Tre", "Quattro"], 2, "Tre single coil con selettore a 5 posizioni.", "d:strat_front"], ["Nel nome Fender, \"mn\" significa…", ["Manico nero", "Tastiera in acero", "Modello mancino", "Made in Mexico"], 1, "mn = maple neck/fingerboard: tastiera in acero, chiara.", "202901"], ["\"rw\" nel nome di una Fender indica…", ["Tastiera in palissandro", "Ponte con vibrato", "Relic finish", "Finitura lucida"], 0, "rw = rosewood, palissandro: tastiera scura.", "202901"], ["Quale modello ha la scala corta da 24\"?", ["Telecaster", "Mustang", "Stratocaster", "Jazzmaster"], 1, "La Mustang: comoda per mani piccole.", "169419"]]}, {"id": "u2l2", "t": "Gibson: Les Paul, SG, ES", "cards": [["Les Paul (1952)", "Corpo in mogano con top in acero bombato, manico incollato, due humbucker. Pesante, sustain lunghissimo, suono grosso: LA chitarra rock.", ["d:lp_front"]], ["SG (1961)", "Nasce come nuova Les Paul: tutta in mogano, sottile, a doppie corna. Leggera, accesso facile ai tasti alti, suono aggressivo (AC/DC, Black Sabbath).", ["d:sg_body"]], ["ES-335 (1958)", "Semiacustica con blocco centrale: calore della cassa, ma niente fischi ad alto volume. Blues, jazz, rock anni '60.", ["d:es_body"]], ["Forme \"estreme\"", "Explorer e Flying V (1958): forme angolari, sceniche, amate dal metal. Firebird: corpo \"rovesciato\" e manico passante.", ["196760", "195729", "198795"]], ["Epiphone", "È il marchio economico di Gibson: le stesse forme ufficiali costruite in Asia. La serie \"Inspired by Gibson\" è la più fedele agli originali.", ["196356", "194941"]]], "ex": {"fa": ["Les Paul", "SG", "ES / semi-hollow"]}, "quiz": [["Quale chitarra ha corpo in mogano, top in acero e due humbucker?", ["Telecaster", "Les Paul", "Stratocaster", "Jazzmaster"], 1, "La Les Paul: suono pieno e sustain lungo.", "d:lp_front"], ["Perché la ES-335 ha un blocco di legno al centro?", ["Per renderla più leggera", "Per evitare i fischi (feedback) ad alto volume", "Per montare il Floyd Rose", "Per avere più tasti"], 1, "Il blocco centrale riduce il feedback mantenendo il calore della cassa.", "d:es_body"], ["La SG rispetto alla Les Paul è…", ["Più pesante", "Più sottile e leggera", "Con corde in nylon", "Senza pickup"], 1, "Corpo sottile tutto in mogano, doppie corna.", "d:sg_body"], ["Epiphone è…", ["Il marchio economico di Fender", "Il marchio economico di Gibson", "Un liutaio spagnolo", "Un modello di Ibanez"], 1, "Epiphone appartiene a Gibson.", "196356"], ["Quale forma è tipica del metal anni '80?", ["Flying V", "Telecaster", "ES-335", "Parlor"], 0, "Flying V ed Explorer sono forme sceniche amatissime dal metal.", "196760"]]}, {"id": "u2l3", "t": "Superstrat e chitarre moderne", "cards": [["La superstrat", "Forma tipo Stratocaster ma con humbucker, 24 tasti, manico sottile e spesso Floyd Rose. Nata negli anni '80 con Charvel e Jackson, resa famosa da Ibanez (serie RG).", ["206370"]], ["Ibanez RG e AZ", "RG = manico Wizard sottilissimo, per rock e metal. AZ = superstrat moderna e versatile per fusion e session.", ["205996", "204930"]], ["PRS Custom 24", "A metà tra Fender e Gibson: scala 25\", due humbucker splittabili, tremolo. È \"la chitarra tuttofare\".", ["177434"]], ["7, 8 corde e baritone", "Corde gravi aggiuntive o scala più lunga per suonare più basso: metal moderno e progressive.", ["204425", "196366"]], ["Headless", "Senza paletta: meccaniche sul ponte, chitarra leggera e bilanciata (Strandberg, Ibanez Q).", ["202093", "196284"]]], "ex": {"u": "7, 8 corde e baritone"}, "quiz": [["Cos'è una superstrat?", ["Una Stratocaster d'epoca", "Una forma tipo Strat con humbucker, manico veloce e spesso Floyd Rose", "Un amplificatore", "Una chitarra a 12 corde"], 1, "Corpo Strat, attitudine metal/rock moderna.", "206370"], ["La serie Ibanez per eccellenza per il metal è…", ["Artcore", "RG", "PF", "Talman"], 1, "La RG con manico Wizard sottile.", "205996"], ["Una chitarra headless…", ["Non ha la paletta", "Non ha i pickup", "Non ha i tasti", "Ha la cassa cava"], 0, "Le meccaniche sono al ponte.", "202093"], ["A cosa serve una settima corda?", ["A suonare più acuto", "Ad avere una corda grave in più per riff pesanti", "A sostituire il truss rod", "A suonare la classica"], 1, "Di solito un Si grave sotto il Mi.", "204425"]]}]}, {"id": "u3", "t": "Pickup e ponti", "d": "Cosa cambia nel suono e nell'uso", "c": "#5b3a8a", "lessons": [{"id": "u3l1", "t": "Single coil, humbucker, P90", "cards": [["Single coil (S)", "Una bobina: suono brillante, cristallino, definito. Difetto: ronzano vicino a luci e computer. Tipici di Strat e Tele.", ["d:strat_body"]], ["Humbucker (H)", "Due bobine in controfase (inventato da Gibson nel 1955): niente ronzio, suono pieno e potente, ideale con la distorsione.", ["d:sg_body"]], ["P90", "Single coil \"grosso\": a metà tra la brillantezza Fender e la grinta di un humbucker. Ronza un po'.", ["197392"]], ["Leggere le sigle", "SSS = tre single coil. HSS = humbucker al ponte + due single. HH = due humbucker. Si legge dal ponte verso il manico.", ["173648", "205690", "197129"]], ["Split e Noiseless", "Coil split: un humbucker che può suonare anche come single coil. Noiseless: single coil progettati per non ronzare.", ["198354", "191246"]], ["Attivi e passivi", "I pickup attivi (EMG, Fishman Fluence) hanno una batteria: uscita alta e suono compresso, molto usati nel metal. Se non suonano, controlla la batteria.", ["205150", "196007"]]], "ex": {"tg": "Pickup HSS"}, "quiz": [["Quale pickup non ronza?", ["Single coil", "Humbucker", "P90", "Tutti ronzano uguale"], 1, "Le due bobine in controfase cancellano il ronzio.", "d:sg_body"], ["HSS significa…", ["Tre humbucker", "Humbucker al ponte e due single coil", "Due humbucker e un single coil", "Tre single coil"], 1, "Si legge dal ponte verso il manico.", "173648"], ["Un cliente suona metal con molta distorsione. Che pickup gli consigli?", ["Single coil", "Humbucker", "Pickup piezo", "Nessun pickup"], 1, "Gli humbucker reggono bene il gain e non ronzano.", "d:sg_body"], ["Cosa permette il coil split?", ["Cambiare le corde più in fretta", "Far suonare un humbucker come un single coil", "Accordare automaticamente", "Collegare due amplificatori"], 1, "Più suoni da un solo pickup.", "198354"], ["Un pickup attivo non suona più. Prima cosa da controllare?", ["Il truss rod", "La batteria", "Il capotasto", "Le meccaniche"], 1, "I pickup attivi funzionano a batteria (di solito 9 V).", "205150"]]}, {"id": "u3l2", "t": "Ponti: fisso, tremolo, Floyd Rose", "cards": [["Ponte fisso", "Stabile, semplice da regolare, sustain lungo. Tune-o-matic (Gibson), a piastra (Tele), hardtail.", ["d:sg_body"]], ["Tremolo / vibrato", "Con la leva si abbassa (e a volte si alza) l'intonazione. Quello classico è il tremolo Strat.", ["d:strat_body"]], ["Floyd Rose", "Ponte a doppio bloccaggio (al ponte e al capotasto): resta accordato anche con uso estremo della leva. Ma cambio corde e setup richiedono molto più tempo: tienilo presente nei preventivi.", ["d:floyd_lp", "d:jackson"]], ["Bigsby", "Vibrato dolce, da rockabilly e country, tipico delle Gretsch.", ["d:gretsch"]]], "ex": {"tg": "Floyd Rose"}, "quiz": [["Quale ponte rende più lungo il cambio corde?", ["Ponte fisso", "Floyd Rose", "Ponte a piastra Tele", "Tune-o-matic"], 1, "Il Floyd Rose blocca le corde al ponte e al capotasto.", "d:floyd_lp"], ["Il Bigsby è tipico di…", ["Gretsch", "Jackson", "Taylor", "Admira"], 0, "Il vibrato Bigsby è un simbolo del suono Gretsch.", "206367"], ["Il vantaggio principale del ponte fisso è…", ["Effetti di vibrato", "Stabilità di accordatura e semplicità", "Più corde", "Suono acustico"], 1, "Meno parti mobili, accordatura più stabile.", "d:sg_body"]]}]}, {"id": "u4", "t": "Acustiche", "d": "Forme, massello e sigle", "c": "#2b6f8f", "lessons": [{"id": "u4l1", "t": "Le forme acustiche", "cards": [["Dreadnought", "La forma più grande e diffusa (Martin): bassi potenti e grande volume. Ideale per accompagnare con il plettro.", ["d:d_front"]], ["Auditorium, OM, 000, Grand Auditorium", "Corpo medio con vita più stretta: più comoda e bilanciata, ottima per il fingerstyle. È la forma più venduta da Taylor.", ["191216", "206398"]], ["Jumbo", "La più grande: bassi profondi, volume enorme (Gibson J-200).", ["45903"]], ["Parlor e da viaggio", "Piccole: suono intimo e medioso. Le \"mini\" (GS Mini, Baby Taylor, 3/4) sono perfette per viaggio e ragazzi.", ["46203", "206373"]], ["Cutaway", "La spalla mancante sul lato basso del corpo permette di arrivare ai tasti alti. Spesso indicata con \"C\" o \"CE\".", ["d:taylor_front"]], ["12 corde", "Sei coppie di corde: suono pieno e scintillante. Più dura da suonare e da accordare.", ["171660"]]], "ex": {"fa": ["Dreadnought", "Auditorium / OM", "Jumbo", "Parlor"]}, "quiz": [["Qual è la forma acustica più diffusa, grande e potente?", ["Parlor", "Dreadnought", "Auditorium", "Travel"], 1, "La dreadnought è la forma inventata da Martin.", "d:d_front"], ["Per un cliente che suona fingerstyle e cerca comodità consigli…", ["Jumbo", "Auditorium / OM", "Dreadnought 12 corde", "Resonator"], 1, "Corpo medio, bilanciato, comodo.", "191216"], ["Cosa indica \"CE\" in una sigla acustica?", ["Corde extra", "Cutaway ed elettronica", "Cedro europeo", "Chitarra economica"], 1, "Cutaway + Electronics.", "44978"], ["La forma più grande in assoluto è…", ["Parlor", "Jumbo", "OM", "Grand Concert"], 1, "Bassi profondi e grande volume.", "45903"]]}, {"id": "u4l2", "t": "Massello o laminato", "cards": [["Massello (solid)", "Una tavola unica di legno vero: suona meglio e migliora con gli anni, ma soffre gli sbalzi di umidità.", ["177486"]], ["Laminato", "Strati di legno incollati: più economico e robusto, suono meno ricco.", ["51318"]], ["Le tre combinazioni", "1) Tutto laminato: le più economiche. 2) Top massello + fondo e fasce laminati: il miglior rapporto qualità-prezzo. 3) Tutto massello: fascia alta.", ["51318", "35873", "199085"]], ["Come riconoscerlo", "Guarda il bordo della buca: se la venatura continua nello spessore è massello, se vedi strati è laminato. E leggi la scheda: \"solid\", \"massello\", \"laminate\".", ["d:d_body"]], ["L'argomento di vendita", "La tavola in massello è la prima cosa da far notare: è il salto di qualità più grande nel suono di un'acustica.", ["45673"]]], "ex": {"tg": "Tutto massello"}, "quiz": [["Qual è la combinazione con il miglior rapporto qualità-prezzo?", ["Tutto laminato", "Top massello, fondo e fasce laminati", "Tutto massello", "Top laminato, fondo massello"], 1, "La tavola è la parte che \"suona\" di più.", "51318"], ["Come riconosci una tavola in massello?", ["Dal colore", "Dal bordo della buca: la venatura continua nello spessore", "Dal peso della chitarra", "Dal numero di tasti"], 1, "Se vedi strati, è laminato.", "d:d_front"], ["Di cosa soffre di più un'acustica in tutto massello?", ["Le corde nuove", "Gli sbalzi di umidità", "Il plettro", "L'amplificatore"], 1, "Va tenuta tra il 45% e il 55% di umidità.", "177486"], ["\"Solid spruce top\" vuol dire…", ["Tavola in abete massello", "Tavola in abete laminato", "Fondo in abete", "Manico in abete"], 0, "Spruce = abete, solid = massello.", "177486"]]}, {"id": "u4l3", "t": "Leggere le sigle Taylor, Martin e Yamaha", "cards": [["Taylor: le tre cifre", "Prima cifra = serie (1 = base, 2, 3 = tutto massello, fino a 9). Seconda = top (1 abete, 2 legno duro, 5 = 12 corde). Terza = forma (0 dreadnought, 2 grand concert, 4 grand auditorium, 6 grand symphony, 7 grand pacific). Es. 214ce = serie 200, top abete, grand auditorium, cutaway ed elettronica.", ["52087", "191216", "195717"]], ["Taylor: le serie", "Academy e serie 100–200: costruite in Messico, top massello. Dalla serie 300 in su: tutto massello, costruite in California. GS Mini: formato ridotto.", ["27721", "46203", "170905"]], ["Martin: lettere e numeri", "D = dreadnought, 000/OM e 00 = corpi medi e piccoli. Il numero è lo \"stile\": 15–17 mogano, 18 mogano e abete, 28 palissandro e abete, 35 e 45 di lusso. La D-28 è LA dreadnought.", ["199085", "174863", "206403"]], ["Martin: le linee", "Serie X (Messico, laminato HPL), Road Series (Messico, massello), Standard (USA), Modern Deluxe e Authentic (alta gamma).", ["25239", "177486"]], ["Yamaha", "FG = folk dreadnought, FS = corpo più piccolo; X = elettrificata, C = cutaway. La serie 800 (FG800, FS800) è la più venduta con top massello. L = alta gamma.", ["35873", "45673", "44977"]]], "ex": {"b": "Taylor"}, "quiz": [["Taylor 214ce: la \"4\" finale indica…", ["Il prezzo", "La forma Grand Auditorium", "Il numero di corde", "L'anno"], 1, "L'ultima cifra è la forma: 4 = grand auditorium.", "52087"], ["Da quale serie Taylor la chitarra è in tutto massello?", ["100", "200", "300", "Academy"], 2, "Dalla serie 300 in su.", "191216"], ["Martin D-28: cosa significa la D?", ["Deluxe", "Dreadnought", "Dark", "Doppio manico"], 1, "D = dreadnought.", "199085"], ["Lo stile Martin 28 è…", ["Mogano e abete", "Palissandro e abete", "Tutto koa", "Laminato HPL"], 1, "Palissandro per fondo e fasce, abete per la tavola.", "199085"], ["Yamaha FGX800C: cosa indicano X e C?", ["Extra e Classic", "Elettrificata e cutaway", "12 corde e cedro", "Mancina e custodia"], 1, "X = elettronica, C = cutaway.", "44977"], ["Taylor 352ce: la \"5\" centrale indica…", ["Top in koa", "12 corde", "Serie 500", "Mancina"], 1, "Il 5 al centro indica la 12 corde.", "168834"]]}]}, {"id": "u5", "t": "Classiche", "d": "Misure, legni e flamenco", "c": "#9a6b12", "lessons": [{"id": "u5l1", "t": "Misure e principianti", "cards": [["Le misure", "4/4 = adulto. 7/8 = dagli 11 anni o adulti minuti. 3/4 = circa 8–11 anni. 1/2 = circa 6–8 anni. 1/4 = circa 4–6 anni. Si sceglie in base all'altezza, non solo all'età.", ["31549", "34656", "49330"]], ["Il primo strumento", "Yamaha C40, Admira Alba, Eko CS10: robuste ed economiche. Dalla Yamaha CG122 o Alhambra 1C la tavola diventa in massello.", ["49330", "206058"]], ["Kit e set", "Chitarra + borsa + accordatore + leggio: il regalo tipico per chi inizia.", ["203376"]], ["Guitalele", "Incrocio tra chitarra e ukulele: sei corde in nylon, corpo minuscolo.", ["45907"]]], "ex": {"u": "Per bambini"}, "quiz": [["Bambino di 7 anni: che misura?", ["4/4", "7/8", "1/2", "12 corde"], 2, "1/2 per circa 6–8 anni, ma conta l'altezza.", "31549"], ["Ragazzo di 10 anni: che misura?", ["1/4", "3/4", "4/4", "Guitalele"], 1, "3/4 per circa 8–11 anni.", "34656"], ["La misura per un adulto è…", ["3/4", "7/8", "4/4", "1/2"], 2, "4/4 è la misura piena.", "49330"]]}, {"id": "u5l2", "t": "Cedro, abete e flamenco", "cards": [["Tavola in cedro", "Suono caldo, pronto, \"già aperto\". Sensibile al tocco leggero: piace a chi studia repertorio romantico.", ["27380"]], ["Tavola in abete", "Suono più chiaro e brillante, si \"apre\" col tempo. Più definizione negli accordi.", ["31365"]], ["Flamenco", "Cassa più sottile, action bassa, legni chiari (cipresso o acero): suono secco e percussivo. Ha il golpeador, il battipenna trasparente per i colpi sulla tavola.", ["d:flam_front"]], ["Classiche per chi viene dall'acustica", "Esistono modelli con manico più stretto (46–48 mm) e cutaway, spesso elettrificati: Yamaha NTX, Ibanez, Alhambra Crossover.", ["78955", "195340"]], ["I marchi spagnoli", "Alhambra, Admira, Raimundo, Ramírez, Almansa: tradizione spagnola dalla chitarra da studio a quella da concerto.", ["37041", "206330"]]], "ex": {"u": "Flamenco"}, "quiz": [["Quale tavola ha un suono più caldo e pronto?", ["Abete", "Cedro", "Acero", "Laminato"], 1, "Il cedro è caldo e risponde subito.", "27380"], ["Cos'è il golpeador?", ["Un tipo di corda", "Il battipenna trasparente della flamenco", "Il ponte", "Una meccanica"], 1, "Protegge la tavola dai colpi.", "31494"], ["Un chitarrista acustico vuole provare il nylon ma trova il manico troppo largo. Proponi…", ["Una classica 4/4 da concerto", "Una classica con manico stretto e cutaway", "Una flamenco", "Una 1/2"], 1, "Manico da 46–48 mm, spesso elettrificata.", "78955"]]}]}, {"id": "u6", "t": "I legni", "d": "Che suono danno e dove si usano", "c": "#6b3e1f", "lessons": [{"id": "u6l1", "t": "Legni del corpo e del manico", "cards": [["Ontano", "Equilibrato e leggero: il corpo classico della Stratocaster.", ["205453"]], ["Frassino", "Brillante, con la venatura in vista: Telecaster e Strat anni '50.", ["167163"]], ["Mogano", "Caldo, ricco di medi: Les Paul, SG, manici e acustiche.", ["d:wood_back"]], ["Acero", "Brillante e definito: manici Fender, top delle Les Paul (quelli \"fiammati\" sono pregiati).", ["d:lp_front"]], ["Tiglio (basswood)", "Leggero e neutro: molte Ibanez e chitarre economiche.", ["194955"]]], "quiz": [["Il corpo classico della Stratocaster è in…", ["Mogano", "Ontano", "Ebano", "Cedro"], 1, "Ontano, oppure frassino.", "205453"], ["Quale legno dà un suono caldo e ricco di medi?", ["Acero", "Mogano", "Abete", "Frassino"], 1, "Il mogano è il legno della Les Paul.", "d:sg_body"], ["Un top \"fiammato\" è di solito in…", ["Acero", "Tiglio", "Mogano", "Palissandro"], 0, "Acero figurato: flame o quilted.", "d:lp_front"]]}, {"id": "u6l2", "t": "Tastiere e tavole", "cards": [["Palissandro (rosewood)", "Tastiera scura, suono caldo con armonici ricchi. Fondo e fasce delle acustiche di pregio.", ["195909"]], ["Ebano", "Nerissimo, durissimo e liscio: attacco netto. Tastiere di alta gamma.", ["d:fretboard"]], ["Alloro e pau ferro", "Alternative al palissandro sulle chitarre di fascia media: suono e aspetto molto simili.", ["192275"]], ["Abete e cedro", "I legni delle tavole armoniche: abete chiaro e potente (Sitka, Engelmann, Adirondack), cedro caldo e pronto.", ["d:wood_top"]], ["Koa, noce, blackwood", "Legni pregiati: koa (Hawaii) brillante che si scalda col tempo, noce bilanciato, blackwood (Australia) caldo e definito.", ["40673"]]], "quiz": [["Quale legno della tastiera è nero, durissimo e liscio?", ["Acero", "Ebano", "Alloro", "Tiglio"], 1, "L'ebano è tipico dell'alta gamma.", "199024"], ["Alloro e pau ferro sono alternative a…", ["Acero", "Palissandro", "Abete", "Mogano"], 1, "Simili per suono e colore.", "192275"], ["Sitka, Engelmann e Adirondack sono tipi di…", ["Mogano", "Abete", "Acero", "Cedro"], 1, "Tre varietà di abete per tavole.", "d:wood_top"]]}]}, {"id": "u7", "t": "Marchi e gamme", "d": "Le scale di prezzo dei grandi marchi", "c": "#a9772a", "lessons": [{"id": "u7l1", "t": "La scala Fender", "cards": [["Squier", "Sonic (la più economica) → Affinity → Classic Vibe (look vintage, ottima qualità). Costruite in Asia.", ["193452", "168929", "202235"]], ["Fender Standard", "La Fender più economica con il logo Fender sulla paletta (Asia).", ["206753"]], ["Messico", "Player e Player II (la Fender più venduta), Player Plus, Vintera (stile vintage per decenni).", ["196615", "201327"]], ["USA", "American Performer → American Professional II (lo standard dei professionisti) → American Ultra (la più moderna). American Vintage II: riedizioni fedeli.", ["26694", "198354"]], ["Custom Shop", "Il vertice: costruite a mano in California, spesso invecchiate (Relic, Journeyman, NOS).", ["201715"]], ["Giappone", "Le Made in Japan sono famose per la precisione e per colori e modelli particolari.", ["177546"]]], "ex": {"b": "Fender"}, "quiz": [["Ordina dalla più economica: quale viene prima?", ["American Professional II", "Squier Affinity", "Player II", "Custom Shop"], 1, "Squier Affinity è la più economica delle quattro.", "168929"], ["Dove sono costruite le Fender Player II?", ["USA", "Messico", "Giappone", "Corea"], 1, "Messico, stabilimento di Ensenada.", "196615"], ["La Fender \"standard\" dei professionisti americani è…", ["Player", "American Professional II", "Vintera", "Squier Classic Vibe"], 1, "Costruita in USA, con custodia rigida.", "26694"], ["Il vertice della produzione Fender è…", ["American Ultra", "Custom Shop", "Made in Japan", "Player Plus"], 1, "Custom Shop, Corona (California).", "201715"], ["La Squier di qualità più alta è…", ["Sonic", "Affinity", "Classic Vibe", "Bullet"], 2, "Classic Vibe: look vintage e pickup Alnico.", "26840"]]}, {"id": "u7l2", "t": "Gibson, PRS, Ibanez, Jackson", "cards": [["Gibson", "Epiphone (Asia) → Gibson USA (Nashville: Standard, Classic, Modern, Special) → Custom Shop e Murphy Lab (invecchiate a mano).", ["196356", "194941", "194920"]], ["PRS", "SE (Asia, la porta d'ingresso) → S2 (USA, lavorazioni semplificate) → Core (USA, alta gamma) → Private Stock.", ["205557", "191246", "177434"]], ["Ibanez", "GIO (economica) → serie Standard (RG, AZES, S) → Premium → Prestige e J.Custom (Giappone).", ["194955", "205996", "200779"]], ["Jackson", "JS (per iniziare) → X Series (fascia media) → Pro → USA.", ["176941", "201834", "203011"]], ["ESP", "LTD (accessibile: più alto il numero, 200 → 400 → 1000, migliore la chitarra) → E-II e ESP (Giappone).", ["196635", "198042", "177186"]]], "ex": {"b": "PRS"}, "quiz": [["Le PRS SE sono costruite…", ["In USA", "In Asia", "In Messico", "In Italia"], 1, "SE = produzione asiatica su progetto americano.", "205557"], ["La PRS americana più accessibile è la…", ["SE", "S2", "Core", "Private Stock"], 1, "S2: costruita in USA con lavorazioni semplificate.", "193954"], ["Le Ibanez di vertice costruite in Giappone sono…", ["GIO", "Prestige", "Artcore", "PF"], 1, "Prestige e J.Custom.", "200779"], ["Nelle ESP LTD, quale serie è più alta?", ["LTD 200", "LTD 400", "LTD 1000", "LTD 100"], 2, "Più alto il numero, migliore la chitarra.", "198042"], ["Le Gibson Murphy Lab sono…", ["Economiche", "Custom Shop invecchiate a mano", "Acustiche", "Chitarre per bambini"], 1, "Finitura invecchiata da Tom Murphy e il suo team.", "194920"]]}, {"id": "u7l3", "t": "Marchi acustici e classici", "cards": [["Martin e Taylor", "Le due grandi americane: Martin più tradizionale (suono caldo e profondo), Taylor più moderna (suono chiaro, manici comodi).", ["199085", "195717"]], ["Yamaha", "Il riferimento per affidabilità e prezzo: dalle C40 e F310 per iniziare alle serie L e Red Label.", ["49330", "171509"]], ["Altre acustiche in negozio", "Lâg (Francia, Tramontane), Furch (Rep. Ceca, tutto massello), Maton e Cole Clark (Australia, amplificazione naturale), Takamine (Giappone, da palco), Crafter (Corea).", ["191878", "172885", "203782"]], ["Eko", "Storico marchio italiano di Recanati: strumenti economici e di fascia media, molto diffusi nelle scuole.", ["30575"]]], "ex": {"b": "Martin"}, "quiz": [["Quale marchio è italiano?", ["Lâg", "Eko", "Furch", "Maton"], 1, "Eko nasce a Recanati.", "30575"], ["Takamine è famosa soprattutto per…", ["Chitarre da metal", "Elettroacustiche da palco", "Chitarre classiche spagnole", "Ukulele"], 1, "Preamp affidabili e suono amplificato naturale.", "177052"], ["Il suono Taylor rispetto a Martin è di solito…", ["Più scuro e profondo", "Più chiaro e bilanciato", "Identico", "Solo amplificato"], 1, "Martin è più caldo, Taylor più moderno e chiaro.", "199085"]]}]}, {"id": "u8", "t": "Vendere", "d": "Domande, fasce di prezzo e abbinamenti", "c": "#b3261e", "lessons": [{"id": "u8l1", "t": "Le domande giuste", "cards": [["Per chi è?", "Per sé, per un figlio, un regalo? Cambia tutto: misura, budget, tipo.", ["34656"]], ["Esperienza e musica", "Ha già suonato? Che musica ascolta o vuole suonare? Suonerà a casa, con amici o dal vivo?", ["194648"]], ["Il budget", "Chiedilo con naturalezza. Poi mostra una chitarra dentro il budget e una appena sopra, spiegando la differenza.", ["35873", "191216"]], ["Cosa ha già", "Amplificatore, custodia, accordatore? Gli accessori completano la vendita.", ["53581"]], ["Far provare", "Una chitarra accordata e con un buon setup si vende da sola. Una scomoda no.", ["d:strat_front"]]], "quiz": [["Qual è la prima domanda utile da fare?", ["Quanto vuoi spendere al massimo?", "Per chi è la chitarra?", "Che marca di corde usi?", "Hai la partita IVA?"], 1, "Capire per chi è orienta tutto il resto.", "34656"], ["Come gestisci il budget?", ["Mostri solo la più cara", "Una chitarra nel budget e una appena sopra, spiegando la differenza", "Solo la più economica", "Non ne parli mai"], 1, "Il cliente sceglie consapevolmente.", "35873"], ["Perché le chitarre esposte devono avere un buon setup?", ["Per legge", "Perché una chitarra scomoda non si vende", "Per pesare meno", "Non serve"], 1, "La suonabilità è il primo argomento di vendita.", "d:strat_front"]]}, {"id": "u8l2", "t": "Abbinare chitarra e cliente", "cards": [["Bambino", "Classica nella misura giusta (1/2 o 3/4), magari in kit.", ["31549"]], ["Adulto principiante, canzoni", "Acustica con top in massello e setup curato: Yamaha FG/FS800, Taylor Academy.", ["35873"]], ["Adulto principiante, rock", "Elettrica entry + piccolo amplificatore (o kit): Squier, Yamaha Pacifica, Epiphone.", ["53581"]], ["Chi suona dal vivo", "Elettroacustica con buon preamp, cutaway, corpo comodo.", ["52087"]], ["Metal", "Humbucker (anche attivi), manico sottile, eventualmente 7 corde: Jackson, ESP LTD, Ibanez RG.", ["206371", "203011"]], ["Le fasce di prezzo", "Fino a 200 € primo strumento · 200–500 € principiante motivato · 500–1.000 € salto di qualità · 1.000–2.000 € esperti · oltre 2.000 € professionisti e collezionisti.", ["51318", "205494", "194941"]]], "quiz": [["Adulto che vuole accompagnare canzoni, budget 350 €. Proponi…", ["Una Les Paul Custom", "Un'acustica con top in massello tipo Yamaha FG800", "Una classica 1/2", "Una 7 corde"], 1, "Top massello e prezzo giusto.", "35873"], ["Ragazzo che vuole suonare metal, primo strumento. Proponi…", ["Gretsch con Bigsby", "Jackson JS o Ibanez GIO con humbucker", "Martin D-28", "Guitalele"], 1, "Humbucker e manico veloce, prezzo da primo strumento.", "176941"], ["Cantautore che suona nei locali. Proponi…", ["Elettroacustica con preamp e cutaway", "Classica 3/4", "Elettrica Floyd Rose", "Resonator"], 0, "Si collega all'impianto e suona naturale.", "52087"], ["Una chitarra da 1.500 € è per…", ["Primo strumento", "Musicisti esperti", "Bambini", "Solo collezionisti"], 1, "Fascia medio-alta.", "204372"]]}]}, {"id": "u9", "t": "Il suono e i generi", "d": "Parlare di suono come un musicista e capire che chitarra serve per ogni genere", "c": "#F2584B", "lessons": [{"id": "u9l1", "t": "Come si descrive un suono", "cards": [["Le tre parole base", "I chitarristi descrivono il suono con tre coppie di parole. Caldo o brillante: quanti bassi e quanti acuti ci sono. Corposo o sottile: quante frequenze medie ci sono, cioè la \"ciccia\" del suono. Pulito o distorto: se il suono resta limpido o si \"sporca\" e diventa ruvido.", ["194941", "196615"]], ["Pulito, crunch, distorto", "Pulito: limpido, come un pianoforte (pop, funk, jazz). Crunch: leggermente sporco, si apre quando suoni forte (blues, rock anni '70). Distorto o high gain: molto saturo e compresso, le note durano a lungo (hard rock, metal). Quando un cliente ti dice \"un suono alla AC/DC\" sta chiedendo un crunch, non un metal.", ["26964"]], ["Attacco e sustain", "L'attacco è come parte la nota: secco e veloce (Telecaster, single coil) o morbido (humbucker al manico). Il sustain è quanto dura la nota dopo che l'hai suonata. Corpi pieni e pesanti, manici incollati e humbucker danno più sustain: per questo la Les Paul è famosa per le note che \"cantano\".", ["194941"]], ["Chi fa il suono di un'elettrica", "In ordine di importanza: le mani di chi suona, poi l'amplificatore e gli effetti, poi i pickup, poi le corde, e solo dopo il legno. Su un'elettrica il legno conta meno di quanto si crede. Se un cliente vuole cambiare suono, chiedigli prima che ampli usa: spesso il problema è lì.", ["195981"]], ["Chi fa il suono di un'acustica", "Qui è il contrario: il legno e la forma contano moltissimo. Conta soprattutto la tavola armonica: in massello vibra di più e migliora con gli anni. Poi la forma: più grande vuol dire più bassi e più volume. Poi i legni di fondo e fasce: il mogano rende il suono più caldo e diretto, il palissandro più ricco di bassi e di alti.", ["199085"]]], "quiz": [["Un cliente vuole un suono \"alla AC/DC\". Che tipo di saturazione cerca?", ["Pulito", "Crunch", "Metal estremo", "Fuzz anni '60"], 1, "AC/DC è il crunch per eccellenza: ampli spinto ma non distortissimo. Chitarre con humbucker e un Marshall fanno quel suono.", "26964"], ["Cosa vuol dire \"sustain\"?", ["Quanto è forte la nota", "Quanto dura la nota dopo averla suonata", "Quanto è distorta", "Quanti bassi ci sono"], 1, "Il sustain è la durata della nota. Corpi pieni e humbucker ne danno di più.", "194941"], ["Su una chitarra elettrica, cosa cambia di più il suono?", ["Il colore della vernice", "L'amplificatore", "La forma della paletta", "Il tipo di tracolla"], 1, "Dopo le mani di chi suona, l'ampli è il fattore più importante. Il legno su un'elettrica pesa meno di quanto si pensa.", "195981"], ["Su un'acustica, cosa cambia di più il suono?", ["Il battipenna", "La tavola armonica e la forma della cassa", "Le meccaniche", "Il colore del binding"], 1, "Su un'acustica la tavola armonica è il cuore del suono: in massello vibra meglio e migliora col tempo.", "199085"], ["Un suono \"corposo\" ha tante…", ["Frequenze medie", "Corde", "Valvole", "Watt"], 0, "Le medie sono la \"ciccia\" del suono. Un suono senza medie sembra sottile e lontano.", null]]}, {"id": "u9l2", "t": "Generi elettrici: che chitarra per cosa", "cards": [["Blues", "Le chitarre classiche del blues sono la Stratocaster (suono morbido e vocale), la semiacustica tipo ES-335 (calda) e la Les Paul (più grassa). L'ampli ideale è un Fender a valvole poco spinto, come il Blues Junior. Il pedale tipico è l'overdrive Tube Screamer.", ["196615", "30346", "199128"]], ["Rock classico", "Les Paul e SG con humbucker, in un ampli in crunch: è il suono di Led Zeppelin, AC/DC e Guns N' Roses. Va bene anche una Strat HSS, cioè con un humbucker al ponte. I marchi di riferimento per l'ampli sono Marshall e Blackstar.", ["194941", "177632"]], ["Hard rock e metal", "Servono humbucker ad alta uscita (spesso attivi, come EMG o Fishman Fluence), un manico sottile e veloce, 24 tasti e a volte il Floyd Rose. I marchi di riferimento sono Ibanez, Jackson, ESP/LTD, EVH, Schecter e Solar. Per le accordature basse si usano 7 corde, 8 corde o baritone. Gli ampli tipici sono EVH 5150, Revv e Blackstar.", ["194650", "52135"]], ["Funk, pop e soul", "Qui si cerca un suono pulito e frizzante. La regina è la Stratocaster nelle posizioni intermedie del selettore (2 e 4). Funziona bene anche la Telecaster. Gli effetti tipici sono il compressore e il chorus. Corde 10-46 o 9-42.", ["202901", "31216"]], ["Jazz", "Si usano hollow body e semiacustiche con humbucker al manico, il tono chiuso e corde spesse (12 e oltre, a volte flatwound, cioè lisce). L'ampli deve essere pulito, senza distorsione. I marchi tipici sono Gibson ES, Ibanez Artcore/AS e Gretsch.", ["d:es_body"]], ["Country", "La Telecaster è la regina: ha l'attacco secco e quel suono \"twang\" tagliente. Funziona bene anche la Gretsch. Si usa un ampli pulito tipo Fender, spesso con un po' di delay corto e di compressore.", ["d:tele_front"]], ["Indie, alternative e shoegaze", "Si usano spesso Jazzmaster, Jaguar, Mustang e Telecaster, cioè forme \"offset\" con suoni particolari. Contano molto gli effetti: riverberi grandi, delay, fuzz, chorus. Al cliente indie, chiedi sempre quali pedali usa.", ["42786"]]], "quiz": [["Un ragazzo suona metal con accordature molto basse. Cosa ha più senso proporgli?", ["Una Telecaster con corde 9-42", "Una 7 corde o una baritone con humbucker ad alta uscita", "Una semiacustica jazz", "Una classica 4/4"], 1, "Per il metal con accordature basse servono più corde o un manico più lungo, più humbucker spinti.", "194650"], ["Qual è la chitarra simbolo del country?", ["Telecaster", "Flying V", "Classica", "Superstrat a 24 tasti"], 0, "Il \"twang\" del country è il suono della Telecaster con il pickup al ponte.", "d:tele_front"], ["Per il funk, quale posizione del selettore di una Strat è la più usata?", ["Solo il ponte", "Le posizioni intermedie (2 e 4)", "Volume a zero", "Nessuna: si usa il fuzz"], 1, "Nelle posizioni 2 e 4 i pickup lavorano in coppia e il suono è \"vetroso\": perfetto per il funk.", "202901"], ["Un cliente vuole il suono del jazz. Che pickup e che ampli?", ["Humbucker al manico e ampli pulito", "Single coil al ponte e fuzz", "Pickup attivi e high gain", "Piezo e ampli acustico"], 0, "Il jazz vuole un suono caldo e pulito: humbucker al manico, tono chiuso e niente distorsione.", "d:es_body"], ["Quali marchi sono tipici del metal?", ["Ibanez, Jackson, ESP/LTD", "Martin, Taylor, Furch", "Alhambra, Admira, Raimundo", "Gretsch, Rickenbacker"], 0, "Ibanez, Jackson, ESP/LTD, EVH e Schecter nascono o sono famosi per rock duro e metal.", "194650"], ["Per il blues, quale pedale è più famoso?", ["Il Tube Screamer (overdrive)", "Il looper", "Il phaser", "L'accordatore"], 0, "Il Tube Screamer verde spinge l'ampli in modo morbido: è il pedale del blues (Stevie Ray Vaughan).", "199128"]]}, {"id": "u9l3", "t": "Generi acustici e classici", "cards": [["Cantautore e accompagnamento", "Per strimpellare accordi e cantare va bene una dreadnought o una jumbo: hanno tanti bassi e tanto volume, e riempiono la stanza. Le dreadnought più classiche sono la Martin D-18 (mogano) e la D-28 (palissandro).", ["199085", "35873"]], ["Fingerstyle e arpeggi", "Chi suona con le dita vuole una cassa più piccola e bilanciata: auditorium, OM, grand concert o parlor. Le note restano separate e chiare. Taylor, con le sue Grand Auditorium, è famosa proprio per questo suono.", ["27721"]], ["Classica e studio", "La classica da studio ha la tavola in abete o in cedro. Il cedro è caldo e pronto subito. L'abete è più brillante e matura con gli anni. Per la scuola di musica e il conservatorio si va su Alhambra, Admira, Raimundo e Yamaha.", ["49330"]], ["Flamenco", "La chitarra flamenca è leggera, con fondo e fasce in cipresso (o palissandro nella versione \"negra\"). Ha le corde basse e il golpeador, cioè la protezione trasparente per i colpi sulla tavola. Il suono è secco, veloce e percussivo.", ["d:flam_front"]], ["Dal vivo: elettrificata", "Chi suona dal vivo ha bisogno di una chitarra con preamplificatore: le sigle sono E, CE, AE. Serve anche un ampli acustico, come l'AER Compact 60 o l'Acus One, oppure basta collegarsi direttamente al mixer.", ["52087", "171665"]]], "quiz": [["Un cliente canta e suona accordi in spiaggia con gli amici. Che forma gli proponi?", ["Dreadnought", "Parlor da studio", "Classica flamenca", "Semiacustica"], 0, "La dreadnought ha volume e bassi: perfetta per accompagnare la voce.", "35873"], ["Che forma preferisce chi suona fingerstyle?", ["Jumbo", "Auditorium/OM, più bilanciata", "Flying V", "Dreadnought 12 corde"], 1, "Una cassa più contenuta dà note più separate e definite: ideale per gli arpeggi.", "27721"], ["Cedro o abete: quale è più caldo e pronto subito?", ["Cedro", "Abete", "Sono identici", "Nessuno dei due"], 0, "Il cedro è caldo e morbido da subito. L'abete è più brillante e matura negli anni.", "49330"], ["Cos'è il golpeador?", ["Una corda speciale", "La protezione trasparente sulla tavola della flamenca", "Un tipo di ponte", "Un capotasto"], 1, "Protegge la tavola dai colpi tipici della tecnica flamenca.", "d:flam_front"], ["Cosa indica la sigla \"CE\" su un'acustica?", ["Corde in Elixir", "Cutaway ed Elettrificata", "Cedro Europeo", "Custodia Esclusa"], 1, "C sta per cutaway (la spalla scavata), E per elettrificata: ha un preamplificatore integrato.", "52087"]]}]}, {"id": "u10", "t": "Marchi a confronto", "d": "Cosa rende unico ogni marchio e quali legni usa", "c": "#F2584B", "lessons": [{"id": "u10l1", "t": "Fender contro Gibson", "cards": [["Due scuole", "Fender (Stratocaster, Telecaster) e Gibson (Les Paul, SG, ES) sono le due \"religioni\" della chitarra elettrica. Quasi tutte le altre chitarre derivano da una delle due. Se capisci la differenza tra loro, capisci il 70% delle elettriche del negozio.", ["196615", "194941"]], ["Manico avvitato o incollato", "Fender avvita il manico al corpo con quattro viti (bolt-on): il suono è più scattante e la riparazione è semplice. Gibson incolla il manico (set neck): il suono è più morbido e il sustain più lungo. Il trucco per riconoscerle: guarda dietro, dove il manico entra nel corpo, e cerca la placca con le viti.", ["d:strat_side", "d:lp_body"]], ["Scala: 25,5 contro 24,75 pollici", "La scala è la lunghezza della corda che vibra. Fender usa 25,5\": le corde sono più tese, il suono più brillante e definito. Gibson usa 24,75\": le corde sono più morbide da piegare (bending), il suono più caldo. Per chi ha le mani piccole, Gibson può risultare più comoda.", ["d:strat_front"]], ["Pickup e legni", "Fender usa di solito single coil (suono brillante e cristallino) e corpi in ontano o frassino con manico in acero. Gibson usa humbucker (grassi e senza ronzio), corpo in mogano con top in acero (la Les Paul) e tastiera in palissandro. Riassunto: Fender è brillante, Gibson è grassa.", ["d:strat_body", "d:lp_body"]], ["Le sorelle economiche", "Squier è il marchio economico di Fender. Epiphone è quello di Gibson. Le forme sono le stesse a un prezzo molto più basso, con legni e componenti più semplici. Al cliente indeciso puoi dire: \"Prima scegli quale famiglia di suono ti piace, poi troviamo la fascia di prezzo giusta\".", ["53581"]]], "quiz": [["Come riconosci un manico avvitato?", ["Dalla paletta", "Dalla placca con quattro viti dietro, dove il manico entra nel corpo", "Dal colore", "Dal numero di tasti"], 1, "Il bolt-on Fender ha la placca con le viti. Il set neck Gibson non ha viti: il manico è incollato.", "d:strat_side"], ["Che scala usa tipicamente Gibson?", ["25,5\"", "24,75\"", "27\"", "22\""], 1, "24,75 pollici: corde un po' più morbide e suono più caldo. Fender usa 25,5\".", "194941"], ["Qual è il marchio economico di Fender?", ["Epiphone", "Squier", "Sterling", "LTD"], 1, "Squier è Fender, Epiphone è Gibson, Sterling è Music Man, LTD è ESP.", "53581"], ["Riassumi in due parole: Fender è…, Gibson è…", ["Grassa / brillante", "Brillante / grassa", "Uguali", "Metal / jazz"], 1, "Single coil e scala lunga danno brillantezza (Fender). Humbucker, mogano e scala corta danno pienezza (Gibson).", null], ["Un cliente fa bending continui e ha mani piccole. Quale scala è più comoda?", ["24,75\" tipo Gibson", "25,5\" tipo Fender", "Baritone 27\"", "Non cambia nulla"], 0, "La scala più corta ha meno tensione: i bending sono più facili e i tasti più vicini.", "194941"]]}, {"id": "u10l2", "t": "I marchi moderni delle elettriche", "cards": [["PRS: la via di mezzo", "Paul Reed Smith ha preso il meglio di Fender e Gibson: scala da 25\", corpo in mogano con top in acero e un suono versatile che va dal pulito al rock. Le SE sono le versioni prodotte in Asia, con un ottimo rapporto qualità-prezzo. La Custom 24 è il modello simbolo.", ["205557"]], ["Ibanez: manici veloci", "È il marchio giapponese degli shredder (Steve Vai, Joe Satriani). Il manico Wizard è molto sottile e piatto. La serie RG è per rock e metal, AZ è più moderna e versatile, GIO è quella per principianti. Fa anche ottime semiacustiche jazz (Artcore, AS).", ["194650", "46110"]], ["Jackson ed ESP/LTD: metal", "Hanno forme aggressive (Rhoads, Kelly, Dinky, Explorer), humbucker potenti e spesso attivi, 24 tasti e manici veloci. LTD è la linea più accessibile di ESP. Le Jackson JS sono le entry level per chi inizia con il metal.", ["173182"]], ["Gretsch: rockabilly e vintage", "Le Gretsch hanno pickup Filter'Tron (humbucker brillanti), spesso il vibrato Bigsby e casse hollow. È il suono di rockabilly, country e rock'n'roll anni '50 (Brian Setzer). La serie Streamliner è quella accessibile.", ["204114"]], ["Yamaha: qualità a ogni prezzo", "La Pacifica è forse la miglior elettrica per principianti per qualità costruttiva: la 012 e la 112 sono classici per iniziare. La Revstar è la linea più \"cafe racer\", con un suono più vintage. Yamaha è sinonimo di affidabilità e controllo qualità.", ["40239"]]], "quiz": [["Che scala usa PRS sulla Custom 24?", ["25\"", "24,75\"", "25,5\"", "30\""], 0, "25 pollici: esattamente a metà tra Gibson e Fender.", "205557"], ["Cosa caratterizza i manici Ibanez Wizard?", ["Molto spessi a U", "Sottili e piatti, veloci", "Senza tasti", "Fatti in plastica"], 1, "Il Wizard è sottilissimo: per questo Ibanez è amata da chi suona tecnico e veloce.", "194650"], ["Un ragazzo vuole iniziare con il metal spendendo poco. Cosa gli proponi?", ["Jackson JS o Ibanez GIO", "Gretsch Streamliner", "Martin D-28", "Classica flamenca"], 0, "Le Jackson JS e le Ibanez GIO hanno forme metal, humbucker e prezzi da entry level.", "173182"], ["Che suono è tipico di Gretsch?", ["Metal moderno", "Rockabilly e rock'n'roll anni '50", "Classica da concerto", "Djent"], 1, "Filter'Tron, Bigsby e casse hollow: è il suono di Brian Setzer e del rockabilly.", "204114"], ["Qual è la linea economica di ESP?", ["LTD", "Squier", "Epiphone", "SE"], 0, "LTD è ESP, SE è PRS, Squier è Fender, Epiphone è Gibson.", null]]}, {"id": "u10l3", "t": "Acustiche: Martin, Taylor, Yamaha e gli altri", "cards": [["Martin: il suono classico americano", "Martin ha inventato la dreadnought. Il suono è profondo, con bassi ricchi e una sensazione \"vintage\". Due modelli da sapere a memoria: la D-18, con fondo in mogano (suono asciutto e diretto), e la D-28, con fondo in palissandro (più bassi e più alti). Piace molto al cantautore e al folk.", ["199085"]], ["Taylor: chiarezza e comodità", "Il suono Taylor è più moderno, brillante e definito: ogni nota si sente bene, anche in un mix. Il manico è comodo e le chitarre sono molto curate. Le sigle numeriche indicano i legni. L'elettronica si chiama Expression System. La serie Academy è il punto di ingresso.", ["27721"]], ["Yamaha: il miglior rapporto qualità-prezzo", "La FG800 è la classica acustica che si consiglia a chi inizia: ha la tavola in massello a meno di 350 €. Le serie A e LL salgono di livello. Yamaha costruisce bene a ogni fascia di prezzo, e questo dà sicurezza al cliente.", ["35873"]], ["Gli altri marchi del negozio", "Lâg (francese) ha ottime acustiche con un design curato. Furch (ceca) fa chitarre in massello di livello alto. Eko è il marchio italiano storico, accessibile. Takamine è famosa per l'elettronica e per l'uso dal vivo. Per le classiche: Alhambra e Admira (Spagna), Raimundo, Yamaha.", ["52087"]]], "quiz": [["Che differenza c'è tra Martin D-18 e D-28?", ["La D-18 ha fondo in mogano, la D-28 in palissandro", "La D-18 ha 18 tasti", "La D-28 è una classica", "Nessuna"], 0, "Mogano: suono più asciutto e diretto. Palissandro: più bassi e alti, suono più \"grande\".", "199085"], ["Come descrivi il suono Taylor in una frase?", ["Scuro e vintage", "Moderno, brillante e definito", "Distorto", "Da flamenco"], 1, "Taylor ha un suono chiaro, con le note ben separate. Martin è più profondo e vintage.", "27721"], ["Qual è l'acustica Yamaha consigliata a chi inizia, con tavola in massello?", ["FG800", "C40", "Pacifica 012", "THR10"], 0, "La FG800 ha la tavola in abete massello a un prezzo da principiante.", "35873"], ["Quale marchio è italiano?", ["Eko", "Furch", "Lâg", "Takamine"], 0, "Eko è il marchio italiano storico. Furch è ceco, Lâg francese, Takamine giapponese.", null]]}, {"id": "u10l4", "t": "I legni usati da ogni marchio", "cards": [["Fender", "Corpo in ontano (equilibrato) o in frassino (brillante e arioso), manico in acero, tastiera in acero (suono brillante e scattante) o in palissandro/pau ferro (più caldo). Le Squier economiche usano spesso pioppo o tiglio.", ["196615", "202901"]], ["Gibson ed Epiphone", "Corpo in mogano (caldo, con le medie piene) con top in acero (aggiunge definizione), manico in mogano, tastiera in palissandro, e in ebano sulle Custom. L'SG è tutta in mogano, senza top in acero: per questo è più \"scura\".", ["194941"]], ["PRS, Ibanez, Jackson", "PRS usa mogano con top in acero, spesso fiammato, e tastiera in palissandro. Ibanez usa spesso tiglio (basswood, leggero e neutro), meranti, nyatoh e tastiera in jatoba o palissandro. Jackson usa pioppo o tiglio sulle economiche e ontano sulle migliori, spesso con tastiera in ebano o amaranto.", ["205557", "194650"]], ["Acustiche: Martin, Taylor, Yamaha", "La tavola quasi sempre è in abete Sitka (forte e brillante) o in cedro (caldo). Fondo e fasce: mogano o sapele (caldo e diretto), palissandro (ricco), acero (brillante, molto definito), koa (dolce, cresce con gli anni). Taylor usa molto ebano sulla tastiera, Yamaha palissandro o noce.", ["199085", "27721"]], ["Come usare questa conoscenza", "Il cliente non compra un legno: compra un suono e una sensazione. Usa il legno per spiegare una differenza che può sentire. Per esempio: \"Questa ha la tastiera in acero, per questo suona più brillante; senti con la stessa chitarra in palissandro\".", []]], "quiz": [["Perché una SG suona più \"scura\" di una Les Paul?", ["È tutta in mogano, senza top in acero", "Ha single coil", "Ha la scala lunga", "Ha la tastiera in acero"], 0, "Il top in acero della Les Paul aggiunge definizione. L'SG, tutta in mogano, è più calda.", null], ["Tastiera in acero o in palissandro: quale è più brillante?", ["Acero", "Palissandro", "Uguali", "Dipende dal colore"], 0, "L'acero è duro e brillante, il palissandro più caldo e morbido.", "196615"], ["Che legno usa spesso Ibanez per il corpo?", ["Tiglio (basswood)", "Koa", "Ebano", "Cipresso"], 0, "Il tiglio è leggero e neutro: si sposa bene con humbucker potenti.", "194650"], ["Qual è la tavola più usata sulle acustiche americane?", ["Abete Sitka", "Pioppo", "Ontano", "Tiglio"], 0, "L'abete Sitka è forte, brillante e regge bene lo strimming energico.", "199085"], ["Ontano o frassino: quale è più brillante e arioso?", ["Frassino", "Ontano", "Uguali", "Nessuno"], 0, "Il frassino (swamp ash) è più arioso, l'ontano è equilibrato.", "202901"]]}]}, {"id": "u11", "t": "Amplificatori", "d": "Come sono fatti, le tecnologie, i marchi e gli abbinamenti giusti", "c": "#F2584B", "lessons": [{"id": "u11l1", "t": "Come è fatto un amplificatore", "cards": [["Il viaggio del suono", "La chitarra manda un segnale debolissimo. L'ampli lo prepara e gli dà il carattere (preamplificatore), poi lo rende potente (finale di potenza), e infine lo trasforma in aria che si muove (il cono o altoparlante, dentro la cassa). Tre parti: preamp, finale, cono.", ["30346"]], ["I comandi principali", "GAIN (o drive) decide quanto è sporco il suono. VOLUME o MASTER decide quanto è forte. Poi l'equalizzatore: BASS (bassi), MIDDLE (medie), TREBLE (acuti). PRESENCE aggiunge brillantezza. REVERB aggiunge l'effetto stanza. Regola d'oro per chi inizia: tutto a ore 12, poi aggiusta.", ["195981"]], ["I canali", "Un canale è un suono preimpostato: canale pulito e canale distorto (lead). Con un footswitch, cioè un pedale, si passa dall'uno all'altro mentre si suona. Gli ampli moderni a modelli hanno tanti canali e preset che si salvano con un tasto.", ["196025"]], ["Combo, testata e cassa", "Il combo ha tutto in un solo mobile: ampli più cono (Blues Junior, Katana). La testata è solo l'ampli, e va collegata a una cassa con dentro i coni: è il classico \"muro\" del rock. Il combo è più pratico. Testata più cassa permette di cambiare la cassa e scegliere il suono.", ["30346", "52135", "194305"]], ["I coni", "Si misurano in pollici: 6,5\", 8\", 10\", 12\". Più è grande il cono, più bassi e più \"aria\" ci sono. Il 12\" è lo standard per suonare con la band. Due coni (2x12, come il Vox AC30) danno un suono più ampio. Una cassa aperta dietro suona più ariosa, una chiusa più compatta e potente sui bassi (metal).", ["26964"]], ["Ingressi e uscite utili", "Uscita cuffie: per suonare di notte. AUX o Bluetooth: per suonare sopra le canzoni. USB: per registrare al computer. Line out: per mandare il suono al mixer. Effect loop: un'uscita e un ingresso per inserire gli effetti tra preamp e finale. Chiedi sempre al cliente dove e come suonerà.", ["44284"]]], "quiz": [["Quale comando decide quanto è distorto il suono?", ["Gain/Drive", "Master", "Reverb", "Presence"], 0, "Il gain spinge il preamplificatore e sporca il suono. Il master regola il volume finale.", "195981"], ["Cos'è un combo?", ["Ampli e cono nello stesso mobile", "Solo la testata", "Un pedale", "Un cavo doppio"], 0, "Combo vuol dire tutto in uno. Testata più cassa sono due pezzi separati.", "30346"], ["Che dimensione di cono è lo standard per suonare con la band?", ["12 pollici", "4 pollici", "6,5 pollici", "18 pollici"], 0, "Il 12\" ha bassi e volume sufficienti per stare insieme alla batteria.", "26964"], ["Un cliente suona di notte in appartamento. Cosa gli serve sull'ampli?", ["L'uscita cuffie", "L'effect loop", "Una testata da 100 W", "Una cassa 4x12"], 0, "Con le cuffie si suona senza disturbare. Alcuni ampli (Katana, THR, Mustang) le hanno ottime.", "44284"], ["Qual è la parte che trasforma il segnale in suono nell'aria?", ["Il cono (altoparlante)", "Il preamp", "Il gain", "Il footswitch"], 0, "Il cono vibra e muove l'aria. Il preamp e il finale lavorano sul segnale elettrico.", null]]}, {"id": "u11l2", "t": "Valvole, transistor e modeling", "cards": [["A valvole", "Dentro ci sono valvole di vetro che si scaldano. Il suono è caldo e dinamico: se suoni piano è pulito, se attacchi forte si sporca in modo naturale. Difetti: sono pesanti, costano di più, le valvole vanno cambiate ogni tanto e suonano al meglio a volume alto. Esempi: Fender Blues Junior, Vox AC30, Blackstar HT, EVH 5150.", ["30346", "26964"]], ["A transistor (solid state)", "Funzionano con circuiti elettronici, senza valvole. Sono robusti, leggeri ed economici, e suonano uguali a qualsiasi volume. Il loro limite storico è la distorsione meno naturale. Esempi: Fender Champion, Blackstar Debut, Laney.", ["197796", "168995"]], ["A modelli (modeling)", "Un computer dentro l'ampli imita decine di ampli e di effetti famosi. Ha preset, app e spesso Bluetooth e USB. È il più versatile per chi suona generi diversi o sta iniziando. Esempi: Boss Katana, Fender Mustang, Yamaha THR, Line6 Catalyst e Spider, Blackstar ID:Core.", ["195981", "198666", "196025"]], ["I Tone Master e gli ibridi", "Fender Tone Master e Marshall Studio sono ampli digitali che copiano un solo ampli a valvole famoso. Hanno lo stesso suono e lo stesso aspetto, ma pesano la metà e non hanno valvole da cambiare. Sono perfetti per chi suona dal vivo e non vuole portare 20 kg.", ["176435", "177632"]], ["I watt: il malinteso più comune", "Più watt non vuol dire più qualità. Un valvolare da 15 W basta già per suonare con un batterista. Un transistor da 15 W va bene per casa. A casa ne bastano 10-20, per le prove con la band servono 50-100 W a transistor oppure 15-40 W a valvole. Un ampli troppo potente a basso volume spesso suona peggio.", ["194222"]]], "quiz": [["Qual è il pregio principale dell'ampli a valvole?", ["Suono caldo e dinamico, reagisce al tocco", "Pesa poco", "Costa poco", "Non si rompe mai"], 0, "La valvola si sporca in modo naturale quando attacchi forte: per molti è il suono più musicale.", "30346"], ["Un ragazzo vuole suonare tanti generi diversi con un solo ampli. Cosa gli proponi?", ["Un ampli a modelli come il Boss Katana", "Un valvolare da 100 W", "Una cassa senza testata", "Un ampli acustico"], 0, "Il modeling copre pulito, crunch, metal ed effetti, con preset e app.", "195981"], ["Basta un valvolare da 15 W per suonare con la batteria?", ["Sì, di solito sì", "No, servono 200 W", "Solo con le cuffie", "Solo all'aperto"], 0, "I watt a valvole \"suonano\" più forte di quelli a transistor: 15 W bastano per le prove.", "194222"], ["Cos'è un Fender Tone Master?", ["Un ampli digitale che copia un valvolare Fender, più leggero", "Un pedale fuzz", "Una testata a valvole da 200 W", "Una chitarra"], 0, "Ha lo stesso suono del valvolare originale, senza valvole e con la metà del peso.", "176435"], ["Per suonare a casa, quanti watt servono in genere?", ["10-20 W", "200 W", "1000 W", "1 W per forza"], 0, "Per casa bastano 10-20 W. Più potenza a volume basso non serve.", "197796"]]}, {"id": "u11l3", "t": "I marchi di amplificatori", "cards": [["Fender", "Il re del pulito: cristallino, con il riverbero a molla \"bagnato\". Blues Junior, Deluxe Reverb e Princeton sono i valvolari leggenda del blues e del pop. Champion e Mustang sono gli ampli per iniziare.", ["30346", "26224", "198666"]], ["Marshall e Vox", "Marshall è il crunch del rock britannico (AC/DC, Slash, Hendrix). Vox con l'AC30 ha un suono \"jangle\", brillante e frizzante: è il suono di Beatles, Queen (Brian May) e U2. Vox fa anche ottimi ampli piccoli: Pathfinder e Mini Go.", ["177632", "26964", "48728"]], ["Boss Katana", "È il campione di vendite tra i modeling: suoni moderni e vintage, effetti Boss integrati, app, ottimo anche in cuffia. Ci sono il Mini X a batteria, il 50 e il 100 W. Ha un rapporto qualità-prezzo difficile da battere.", ["195981", "199078"]], ["Blackstar, EVH, Orange", "Blackstar: suono britannico moderno, con il controllo ISF per passare dal suono \"americano\" a quello \"inglese\"; Debut per iniziare, HT a valvole. EVH 5150: il suono metal di Eddie Van Halen, saturo e compatto. Orange: arancione, grosso e grezzo (stoner, rock). Il Terror Stamp è un mini ampli da pedaliera.", ["196132", "194222", "191025"]], ["Yamaha THR e Line6", "Yamaha THR è l'ampli da salotto: bello, con suono stereo, Bluetooth e batteria. Piace a chi suona a casa e non vuole \"un ampli da cantina\". Line6 ha inventato il modeling: Spider per iniziare, Catalyst moderno, e Helix (multieffetto) per i professionisti.", ["44284", "196025"]], ["Boutique: Koch, Supro, Revv", "Sono ampli artigianali di fascia alta. Koch (olandese) è versatile, Supro ha un suono vintage americano grezzo, Revv è canadese e potentissimo per il metal moderno. Il cliente che li chiede sa già cosa vuole: ascoltalo e fallo provare.", ["30317", "192306"]]], "quiz": [["Quale marchio è famoso per il pulito cristallino e il riverbero a molla?", ["Fender", "EVH", "Orange", "Revv"], 0, "Il pulito Fender con il riverbero a molla è il suono di riferimento per blues, surf e pop.", "26224"], ["Che ampli usava Brian May dei Queen?", ["Vox AC30", "EVH 5150", "Boss Katana", "Yamaha THR"], 0, "L'AC30 è il suono di Queen, Beatles e U2.", "26964"], ["Per il metal moderno saturo, quale marchio è un riferimento?", ["EVH 5150", "Fender Princeton", "AER", "Acus"], 0, "Il 5150 nasce per l'high gain di Eddie Van Halen.", "194222"], ["Un cliente vuole un ampli bello da tenere in salotto, con Bluetooth. Cosa gli proponi?", ["Yamaha THR", "Una testata EVH con cassa", "Un Marshall 4x12", "Un ampli acustico AER"], 0, "Il THR è pensato per casa: estetica curata, suono stereo, Bluetooth.", "44284"], ["Cos'è l'Orange Terror Stamp?", ["Un mini ampli da pedaliera", "Una cassa 4x12", "Un plettro", "Un accordatore"], 0, "È un ampli in formato pedale: lo metti sulla pedaliera e lo colleghi a una cassa.", "191025"], ["Qual è il punto forte del Boss Katana?", ["Versatilità e rapporto qualità-prezzo", "È solo a valvole", "Ha solo il pulito", "È per acustiche"], 0, "Tanti suoni ed effetti Boss, app e cuffia: per questo vende tantissimo.", "195981"]]}, {"id": "u11l4", "t": "Abbinare chitarra e ampli", "cards": [["Strat e Tele", "I single coil amano i puliti e i crunch leggeri: Fender (Blues Junior, Deluxe, Tone Master) o Vox. Con un Katana, scegli il canale Clean o Crunch. Se il cliente vuole il metal con una Strat SSS, avvisalo che i single coil ronzano con molto gain.", ["196615", "30346"]], ["Les Paul, SG e humbucker", "Gli humbucker vanno bene con il crunch britannico: Marshall, Blackstar, Vox spinto. È il suono rock per eccellenza. Anche un Katana sul canale Brown o Lead va benissimo.", ["194941", "196132"]], ["Metal", "Superstrat con humbucker potenti più un ampli ad alto gain: EVH 5150, Revv, Blackstar, oppure i modeling (Katana, Line6, Helix). Aggiungi un noise gate per togliere i fruscii tra un riff e l'altro.", ["194650", "52135"]], ["Chi inizia", "Va bene un ampli piccolo a modelli o a transistor, con l'uscita cuffie: Katana Mini X, Fender Champion II 25, Mustang LT40S, Blackstar Debut. Il kit chitarra più ampli è la soluzione più semplice per i genitori.", ["197796", "198666", "53581"]], ["Acustiche: serve l'ampli acustico", "Un'acustica collegata a un ampli per elettrica suona male, perché quell'ampli taglia acuti e bassi. Serve un ampli acustico, che riproduce tutto lo spettro come un piccolo impianto: Laney LA15C e Ibanez Troubadour per iniziare, Fender Acoustic 100, Acus One e AER Compact 60 per i professionisti. Spesso hanno anche un ingresso per il microfono.", ["171665", "25292", "171050"]], ["Silenzio e cuffie", "Per suonare senza disturbare ci sono il Fender Mustang Micro, che si attacca alla chitarra e si collega alle cuffie, e il Boss Waza-Air, cuffie wireless che simulano un ampli nella stanza. Un'ottima idea regalo.", ["197390", "26052"]]], "quiz": [["Un cliente compra un'acustica elettrificata per suonare in un locale. Che ampli gli proponi?", ["Un ampli acustico tipo AER o Acus", "Un EVH 5150", "Un Marshall crunch", "Un Orange Terror"], 0, "Gli ampli per elettrica tagliano le frequenze: l'acustica suonerebbe \"inscatolata\".", "171665"], ["Con una Les Paul, quale ampli dà il classico suono rock?", ["Un Marshall o Blackstar in crunch", "Un ampli acustico", "Un ampli per basso", "Nessuno"], 0, "Humbucker più crunch britannico è il suono del rock classico.", "196132"], ["Genitore con budget limitato, figlio che inizia l'elettrica. Che ampli?", ["Fender Champion II 25 o Blackstar Debut", "Fender '65 Deluxe Reverb", "Revv D25", "EVH 5150III 50 W"], 0, "Piccoli, economici, con l'uscita cuffie: perfetti per iniziare.", "197796"], ["Cosa sono le Boss Waza-Air?", ["Cuffie wireless che simulano un ampli", "Un pedale wah", "Corde rivestite", "Una testata a valvole"], 0, "Le colleghi alla chitarra senza fili e sembra di avere un ampli nella stanza.", "26052"], ["Strat SSS e tanto gain: cosa dici al cliente?", ["Che i single coil ronzano con molto gain", "Che non si può collegare", "Che deve cambiare tastiera", "Niente, è perfetta"], 0, "I single coil prendono più disturbi: per il metal si preferiscono gli humbucker.", "196615"]]}]}, {"id": "u12", "t": "Gli effetti a pedale", "d": "Saturazione, modulazioni, eco e come si costruisce una pedaliera", "c": "#F2584B", "lessons": [{"id": "u12l1", "t": "Overdrive, distorsione e fuzz", "cards": [["Overdrive", "Imita un ampli a valvole spinto: il suono è caldo e morbido, e risponde a quanto forte suoni. Il re è l'Ibanez Tube Screamer (TS808), quello verde. Molti chitarristi lo usano anche come \"spinta\" per un ampli già un po' distorto: il suono si stringe e diventa più definito.", ["199128", "194693"]], ["Distorsione", "È più satura e compressa dell'overdrive: il suono è più rock e più duro. Il classico è il Boss DS-1, quello arancione, usato da Kurt Cobain e da Joe Satriani. Costa poco ed è indistruttibile.", ["198940"]], ["Fuzz", "Il suono è \"squadrato\", grasso e un po' ronzante: è il suono degli anni '60 (Hendrix, Rolling Stones) e dello stoner e del rock grezzo moderno. È il più estremo dei tre.", []], ["Boost", "Il boost alza il volume e la spinta del segnale senza cambiare molto il carattere del suono. Serve per gli assoli, o per spingere un ampli a valvole.", []], ["Come spiegarlo al cliente", "Un esempio semplice: l'overdrive è come alzare la voce, la distorsione è come urlare, il fuzz è come urlare in un megafono rotto. Chiedi sempre: \"Che band ti piace?\" Il genere ti dice di quale dei tre ha bisogno.", []]], "quiz": [["Qual è l'overdrive più famoso della storia?", ["Ibanez Tube Screamer", "Boss RC-1", "TC Polytune", "Dunlop Cry Baby"], 0, "Il Tube Screamer verde è il pedale del blues e uno dei più copiati.", "199128"], ["Che pedale è il Boss DS-1?", ["Distorsione", "Delay", "Accordatore", "Looper"], 0, "Il DS-1 arancione è la distorsione economica e indistruttibile per eccellenza.", "198940"], ["Quale dei tre è il più estremo e \"squadrato\"?", ["Fuzz", "Overdrive", "Boost", "Chorus"], 0, "Il fuzz taglia l'onda del suono in modo drastico: grasso e ronzante.", null], ["Un cliente suona blues con un Fender pulito e vuole un po' di grinta. Cosa gli proponi?", ["Un overdrive tipo Tube Screamer", "Un fuzz estremo", "Un looper", "Un phaser"], 0, "L'overdrive aggiunge una saturazione morbida che reagisce al tocco: perfetta per il blues.", "199128"], ["A cosa serve un boost?", ["Ad alzare volume e spinta senza cambiare il carattere", "Ad accordare", "A fare l'eco", "A registrare"], 0, "Serve per far emergere gli assoli o per spingere l'ampli.", null]]}, {"id": "u12l2", "t": "Delay, riverbero e modulazioni", "cards": [["Delay (eco)", "Ripete la nota dopo un tempo che decidi tu. Un delay corto \"ingrossa\" il suono, uno lungo crea atmosfera (The Edge degli U2, Pink Floyd). Il delay analogico, come l'MXR Carbon Copy, ha ripetizioni calde che si scuriscono. Quello digitale, come il Boss DD-8 o il TC Flashback, è pulito e ha tante funzioni.", ["34846", "36760", "45335"]], ["Riverbero", "Simula il suono di una stanza, di una sala o di una chiesa. Molti ampli ce l'hanno già. Come pedali: Boss RV-6, versatile, e Strymon BigSky, di fascia alta, con riverberi enormi per post-rock e ambient.", ["34594", "42786"]], ["Chorus, phaser, flanger", "Sono le modulazioni, cioè effetti che fanno \"muovere\" il suono. Il chorus raddoppia il suono come se suonassero due chitarre: è il suono anni '80 e dei Nirvana nei puliti (Boss CE-2W). Il phaser crea un vortice: il Phase 90 arancione di Van Halen. Il flanger fa l'effetto \"aereo a reazione\".", ["31216", "34862"]], ["Wah-wah", "È un pedale che si muove con il piede e fa \"parlare\" la chitarra: è il suono di Hendrix, Slash e del funk anni '70. Il classico è il Dunlop Cry Baby GCB95.", ["25391"]], ["Looper", "Registra quello che suoni e lo ripete in loop: ci suoni sopra. È perfetto per studiare, per l'improvvisazione e per chi suona da solo dal vivo. Boss RC-1 e TC Ditto X2 sono i più semplici da usare.", ["48011", "47929"]]], "quiz": [["Che effetto è l'MXR Carbon Copy?", ["Delay analogico", "Distorsione", "Accordatore", "Wah"], 0, "Il Carbon Copy è il delay analogico più venduto: ripetizioni calde.", "34846"], ["Quale effetto simula una stanza o una chiesa?", ["Riverbero", "Wah", "Fuzz", "Looper"], 0, "Il riverbero ricrea lo spazio di un ambiente.", "34594"], ["Il suono del pulito anni '80 \"doppio e ondeggiante\" è…", ["Chorus", "Overdrive", "Boost", "Noise gate"], 0, "Il chorus raddoppia il segnale con una leggera oscillazione: il Boss CE-2 ne ha fatto la storia.", "31216"], ["Un cliente suona da solo nei locali e vuole accompagnarsi. Cosa gli serve?", ["Un looper", "Un wah", "Un fuzz", "Un phaser"], 0, "Con il looper registra gli accordi e poi ci canta sopra o fa l'assolo.", "48011"], ["Che pedale si muove con il piede e fa \"parlare\" la chitarra?", ["Wah-wah (Cry Baby)", "Delay", "Accordatore", "Chorus"], 0, "Il Cry Baby è il wah classico: Hendrix, Slash, funk.", "25391"]]}, {"id": "u12l3", "t": "La pedaliera: ordine e alimentazione", "cards": [["Il primo pedale: l'accordatore", "In ogni pedaliera seria il primo pedale è l'accordatore: Boss TU-3, TC Polytune 3 (che accorda tutte le corde insieme), D'Addario. Quando lo premi, il suono si spegne e puoi accordare in silenzio sul palco. È l'accessorio più facile da abbinare.", ["25430", "48777"]], ["L'ordine classico", "Partendo dalla chitarra: accordatore, poi wah, poi compressore, poi overdrive e distorsione, poi modulazioni (chorus, phaser), poi delay, e infine riverbero. Facile da ricordare: prima si \"forma\" il suono, poi lo si mette nello spazio. Non è una legge, ma è il punto di partenza giusto.", []], ["Alimentazione", "Quasi tutti i pedali vanno a 9 V, con il polo negativo al centro. Usare un alimentatore sbagliato, cioè con la tensione o la polarità sbagliata, può bruciarli. Per un pedale solo basta l'alimentatore della marca (Boss PSA-230S). Per tanti pedali serve un'alimentazione multipla isolata, che evita i ronzii.", ["30788"]], ["Multieffetto: tutto in una scatola", "Contiene ampli, effetti e preset in un solo prodotto. È perfetto per chi inizia o per chi vuole tanti suoni senza spendere in pedali singoli. In ordine di fascia: Zoom G2 Four, Mooer GE200, Boss GX-100, fino al Line6 Helix, lo standard dei professionisti.", ["176344", "26407", "171867", "46676"]], ["Pedali singoli o multieffetto?", "Pedali singoli: suono specifico, semplicità, piacere di collezionarli. Multieffetto: tanti suoni, cuffie, registrazione e prezzo per suono più basso. Domanda chiave al cliente: \"Vuoi pochi suoni perfetti o tanti suoni da esplorare?\"", ["46676", "199128"]]], "quiz": [["Qual è il primo pedale della catena?", ["L'accordatore", "Il riverbero", "Il delay", "Il chorus"], 0, "L'accordatore va per primo: riceve il segnale pulito e spegne il suono quando accordi.", "25430"], ["In una catena classica, dove va il riverbero?", ["Alla fine", "All'inizio", "Prima del wah", "Prima dell'accordatore"], 0, "Il riverbero va per ultimo: mette tutto il suono \"nella stanza\".", "34594"], ["Quasi tutti i pedali funzionano a…", ["9 V con negativo al centro", "220 V", "1,5 V", "18 V positivo al centro"], 0, "Lo standard è 9 V con negativo al centro. Alimentatori sbagliati possono bruciarli.", "30788"], ["Qual è il multieffetto di riferimento dei professionisti?", ["Line6 Helix", "Boss RC-1", "Dunlop Cry Baby", "Boss TU-3"], 0, "L'Helix è lo standard da palco e da studio.", "46676"], ["Cosa ha di speciale il TC Polytune?", ["Accorda tutte le corde insieme", "Fa il delay", "È un fuzz", "Registra"], 0, "Suoni tutte le corde a vuoto e vedi subito quali sono stonate.", "48777"], ["Quale multieffetto proponi a un principiante con budget basso?", ["Zoom G2 Four", "Line6 Helix", "Strymon BigSky", "EVH 5150III"], 0, "Lo Zoom G2 Four costa poco e ha tanti suoni e cuffie.", "176344"]]}]}, {"id": "u13", "t": "Corde e accessori", "d": "Scalature, materiali e il kit giusto per ogni chitarra", "c": "#F2584B", "lessons": [{"id": "u13l1", "t": "Le corde", "cards": [["La scalatura", "I numeri sulla confezione sono lo spessore della corda più sottile e di quella più grossa, in millesimi di pollice. Su un'elettrica, 10-46 è lo standard. 9-42 è più morbida (per principianti e per i bending). 11 e oltre è più dura e serve per le accordature basse o per il jazz. Sulle acustiche si parte da 12-53 (light).", ["193930", "175102"]], ["I materiali", "Elettrica: nichel (nickel wound), la più usata. Acustica: bronzo 80/20, brillante appena montata ma dura meno, oppure phosphor bronze, più calda e più duratura. Classica: nylon, con i bassi rivestiti, e la tensione indicata (normal, high, light). Le D'Addario EJ45 sono le classiche più vendute.", ["167102", "29994"]], ["Corde rivestite", "Le Elixir e le D'Addario XS hanno un rivestimento sottile che le protegge dal sudore: durano 3-4 volte di più. Costano di più, ma per chi suona tanto o ha mani che sudano si risparmia. È un ottimo argomento di vendita.", ["42375", "175102"]], ["Quando cambiarle", "Le corde vanno cambiate se sono scure, ruvide o arrugginite, se il suono è spento o se non tengono più l'accordatura. Chi suona tutti i giorni le cambia ogni 1-2 mesi, chi suona poco ogni 3-4. Proponi sempre un set di scorta con la chitarra.", ["193930"]], ["Gli errori da evitare", "Mai montare corde d'acciaio su una classica: si danneggiano manico e ponte. Mai nylon su un'acustica. Se il cliente cambia scalatura in modo importante, per esempio da 9 a 11, la chitarra va regolata: truss rod, altezza delle corde e intonazione.", ["d:cla_front"]]], "quiz": [["Qual è la scalatura standard di un'elettrica?", ["10-46", "13-56", "28-43", "45-105"], 0, "10-46 è il punto di riferimento. 9-42 è più morbida, 11+ più dura.", "193930"], ["Qual è il vantaggio delle corde rivestite (Elixir)?", ["Durano 3-4 volte di più", "Costano meno", "Sono per classica", "Non vanno mai accordate"], 0, "Il rivestimento le protegge dal sudore e dallo sporco.", "42375"], ["Che corde metti su una classica?", ["Nylon (es. D'Addario EJ45)", "Nichel 10-46", "Phosphor bronze 12-53", "Flatwound 12-52"], 0, "Le classiche usano solo nylon. L'acciaio le danneggia.", "29994"], ["Phosphor bronze rispetto a 80/20: cosa cambia?", ["Più calda e dura di più", "È per elettrica", "È in nylon", "È identica"], 0, "La 80/20 è brillante ma si spegne prima. La phosphor bronze è più calda e longeva.", "167102"], ["Un principiante si lamenta che le corde fanno male alle dita. Cosa consigli?", ["Una scalatura più leggera (es. 9-42) e un buon setup", "Corde più grosse", "Niente", "Corde di nylon su un'elettrica"], 0, "Corde più sottili e un'azione bassa rendono la chitarra molto più facile da suonare.", "193930"]]}, {"id": "u13l2", "t": "Il kit giusto per ogni chitarra", "cards": [["Elettrica", "Con un'elettrica servono sempre: un ampli (o le cuffie), un cavo jack, plettri, una tracolla, un accordatore, una borsa e un set di corde di scorta. Senza ampli e cavo un'elettrica non suona: non dare mai per scontato che il cliente li abbia già.", ["202642", "201817", "177199"]], ["Acustica", "Servono: un accordatore, un capotasto (indispensabile per chi canta, perché adatta la tonalità alla voce), una borsa imbottita, plettri sottili o medi, corde di scorta e un supporto. In inverno, con il riscaldamento acceso, è utile un umidificatore.", ["25246", "30915"]], ["Classica", "Servono: una borsa, un poggiapiede (la postura classica lo richiede), un leggio per gli spartiti, un accordatore e un set di corde. Per i bambini, controlla che la misura sia giusta (1/4, 1/2, 3/4, 4/4).", ["27349", "200624", "29602"]], ["Il kit per iniziare", "Per chi parte da zero, il kit (chitarra più ampli più accessori) è la soluzione più semplice e conveniente: un genitore lo capisce subito. Se il kit non c'è, componilo tu e mostra il prezzo totale.", ["53581"]], ["Come proporlo senza sembrare insistente", "Non dire \"vuoi anche…?\", ma \"Per iniziare ti servono queste tre cose\". Spiega a cosa serve ciascuna. Il cliente lo vive come un aiuto, perché a casa non può suonare senza un cavo o un accordatore.", []]], "quiz": [["Un cliente compra la sua prima elettrica. Cosa NON deve mancare?", ["Ampli (o cuffie) e cavo", "Un capotasto per classica", "Un poggiapiede", "Corde in nylon"], 0, "Senza ampli e cavo un'elettrica non si sente.", "202642"], ["A cosa serve il capotasto mobile?", ["A cambiare tonalità per adattarsi alla voce", "Ad accordare", "A pulire le corde", "A tenere la chitarra"], 0, "Si mette su un tasto e alza tutta la chitarra: chi canta lo usa tantissimo.", "25246"], ["Quale accessorio è tipico della chitarra classica?", ["Il poggiapiede", "Il wah", "La testata", "Il cavo jack"], 0, "Il poggiapiede alza la gamba sinistra per la postura classica corretta.", "27349"], ["Qual è la frase migliore per proporre gli accessori?", ["\"Per iniziare ti servono queste tre cose\"", "\"Vuoi spendere di più?\"", "\"Prendi tutto il catalogo\"", "Non dire niente"], 0, "Proporli come un aiuto pratico funziona meglio di una domanda chiusa.", null], ["Per un'acustica in inverno, con il riscaldamento acceso, cosa è utile?", ["Un umidificatore", "Un fuzz", "Una testata", "Corde 9-42"], 0, "L'aria secca fa ritirare il legno: possono uscire i bordi dei tasti o crepe sulla tavola.", "30915"]]}, {"id": "u13l3", "t": "Accessori: come sceglierli", "cards": [["Cavi", "3 metri per casa, 6 metri per il palco. Il jack angolato serve per pedali e chitarre con l'uscita sul fronte. Un cavo troppo economico fa rumore e si rompe: un buon cavo, come Pig Hog o D'Addario, dura anni.", ["202642", "204264"]], ["Plettri", "Lo spessore cambia tutto. Thin (circa 0,5 mm) per strimpellare accordi sull'acustica. Medium (circa 0,7 mm) va bene per tutto. Heavy (circa 1 mm e oltre) e i Jazz III piccoli e rigidi per assoli precisi e metal. Il Fender 351 è la forma classica.", ["201449", "202483"]], ["Tracolle", "Tracolla larga (5-6 cm) per chitarre pesanti come una Les Paul. Materiale: nylon o cotone (economico) e pelle (più bella e durevole). Se il cliente suona in piedi dal vivo, proponi anche gli strap lock, che bloccano la tracolla e fanno sì che la chitarra non cada.", ["201817", "201243"]], ["Borse e custodie", "Borsa leggera (circa 10 mm di imbottitura): per casa e brevi spostamenti. Borsa imbottita (20 mm e oltre): per il trasporto frequente. Custodia rigida: per chitarre costose, viaggi e voli. Regola pratica: più vale la chitarra, più seria deve essere la protezione.", ["177199", "171975", "195472"]], ["Pulizia e cura", "Panno in microfibra per il corpo. Olio di limone (lemon oil) solo sulle tastiere non verniciate, in palissandro o in ebano: mai sull'acero verniciato. Il detergente per corde allunga la loro vita. Il multi-tool e la chiave del truss rod servono per piccole regolazioni.", ["29323", "26962", "52679", "28632"]]], "quiz": [["Che plettro consigli per strimpellare accordi sull'acustica?", ["Thin, sottile", "Jazz III heavy", "Plettro in metallo", "Nessuno"], 0, "Il plettro sottile scivola sulle corde e rende lo strimming morbido.", "201449"], ["Su quale tastiera NON si usa l'olio di limone?", ["Acero verniciato", "Palissandro", "Ebano", "Pau ferro"], 0, "Il lemon oil è per i legni non verniciati. L'acero verniciato si pulisce con un panno.", "29323"], ["A cosa servono gli strap lock?", ["A bloccare la tracolla perché la chitarra non cada", "Ad accordare", "A cambiare le corde", "A collegare i pedali"], 0, "Chi suona in piedi dal vivo li apprezza tantissimo.", "201817"], ["Un cliente vola spesso con una chitarra da 2.000 €. Cosa gli proponi?", ["Una custodia rigida", "Una borsa da 5 mm", "Niente", "Un panno"], 0, "Per viaggi e chitarre di valore la custodia rigida è d'obbligo.", "195472"], ["Quanto deve essere lungo il cavo per suonare sul palco?", ["Circa 6 metri", "30 cm", "50 metri", "1 metro"], 0, "6 metri danno libertà di movimento. Per casa bastano 3 metri.", "204264"]]}]}, {"id": "u14", "t": "Che chitarra per chi", "d": "Principiante, intermedio, esperto: cosa proporre e perché", "c": "#F2584B", "lessons": [{"id": "u14l1", "t": "Il principiante", "cards": [["Cosa conta davvero", "Per chi inizia, la cosa più importante non è la marca ma la suonabilità: corde basse, un manico comodo e una chitarra che resti accordata. Una chitarra scomoda fa smettere di suonare. Una chitarra ben regolata fa innamorare.", []], ["Elettrica: 150-350 €", "Squier Affinity e Sonic, Yamaha Pacifica 012/112, Ibanez GIO, Jackson JS. La Pacifica 112 è famosa per la qualità al suo prezzo. Per chi sogna il metal: Ibanez GIO o Jackson JS. Proponi il kit con l'ampli, se esiste.", ["40239", "53015", "46110"]], ["Acustica: 200-400 €", "La Yamaha FG800 (tavola in massello) è la risposta più sicura. Alternative: Eko e Taylor Academy se il budget sale. Se il cliente ha le mani piccole o vuole comodità, proponi una forma più piccola (auditorium, parlor) con le corde light.", ["35873", "27721"]], ["Classica e bambini", "La misura dipende dall'altezza del bambino. Indicativamente: 1/4 per circa 4-6 anni, 1/2 per circa 6-8, 3/4 per circa 8-11, 4/4 da circa 11-12 anni. Yamaha C40 e CS40 (3/4) sono classici sicuri. Se puoi, fai sedere il bambino con la chitarra in mano.", ["49330", "34656"]], ["Perché non la più economica in assoluto", "Spiegalo così: \"Con poco di più ha una tastiera migliore e tiene l'accordatura: imparerà più velocemente e non si scoraggerà\". Non è spingere a spendere: è evitare che la chitarra finisca sotto il letto.", []]], "quiz": [["Per un principiante, cosa conta più della marca?", ["La suonabilità: corde basse e accordatura stabile", "Il colore", "Avere 24 tasti", "I pickup attivi"], 0, "Una chitarra comoda e ben regolata fa continuare a suonare.", null], ["Quale acustica economica ha la tavola in massello ed è un classico per iniziare?", ["Yamaha FG800", "Martin D-28", "Taylor 814", "Gibson J-45"], 0, "La FG800 ha la tavola in abete massello a un prezzo da principiante.", "35873"], ["Bambino di circa 9 anni. Quale misura di classica?", ["3/4", "4/4", "1/4", "Non importa"], 0, "Tra gli 8 e gli 11 anni circa si usa di solito la 3/4. Meglio comunque provarla.", "34656"], ["Un ragazzino vuole fare metal e spendere poco. Cosa gli proponi?", ["Ibanez GIO o Jackson JS", "Gretsch Streamliner", "Classica 1/2", "Martin D-18"], 0, "Forma da metal, humbucker e prezzo da entry level.", "46110"], ["Come giustifichi qualche euro in più rispetto alla più economica?", ["Tiene l'accordatura ed è più comoda: impara più in fretta", "Perché sì", "È più colorata", "Ha più watt"], 0, "Il valore è nella suonabilità, non nel lusso.", null]]}, {"id": "u14l2", "t": "L'intermedio", "cards": [["Chi è", "Suona da 1-3 anni, ha una chitarra base e sente che \"gli manca qualcosa\". Vuole un salto di qualità vero: suono migliore, componenti più affidabili e una chitarra che lo accompagni per anni.", []], ["Elettrica: 500-1.000 €", "Fender Player II (Messico), PRS SE, Epiphone Inspired by Gibson, Ibanez di fascia media, Yamaha Revstar, Gretsch Electromatic. Rispetto alla chitarra base hanno pickup migliori, meccaniche più precise, legni migliori e una finitura più curata, e mantengono meglio il loro valore se un giorno le rivende.", ["202901", "205557"]], ["Acustica: 500-1.200 €", "In questa fascia si passa a tavola in massello di qualità o tutto massello, ed elettronica migliore: Taylor serie 100-200, Yamaha serie A, Lâg, Martin serie Road/X. La differenza si sente in volume, definizione e in come suona dopo qualche anno.", ["27721"]], ["Spesso il collo di bottiglia è l'ampli", "Se ha una buona chitarra e un ampli da 10 W economico, migliorare l'ampli (Katana, Blues Junior, Tone Master) spesso cambia il suono più di una chitarra nuova. Dirlo crea fiducia: il cliente capisce che pensi al suo suono, non allo scontrino.", ["195981", "30346"]], ["Domande da fare", "Cosa ti manca nella chitarra che hai? Che musica fai adesso? Suoni con altri? Hai un ampli? Le risposte ti portano dritto alla proposta giusta.", []]], "quiz": [["Un intermedio ha una buona chitarra ma un ampli economico da 10 W. Cosa è più utile?", ["Migliorare l'ampli", "Comprare un'altra chitarra uguale", "Cambiare la tracolla", "Niente"], 0, "Spesso l'ampli è il collo di bottiglia del suono.", "195981"], ["Cosa ottiene un intermedio passando a una chitarra da 500-1.000 €?", ["Pickup, meccaniche e legni migliori e un valore che regge", "Più corde", "Solo un colore diverso", "Niente"], 0, "Il salto si sente nel suono e nell'affidabilità.", "202901"], ["Quale di queste è una tipica elettrica di fascia intermedia?", ["Fender Player II Stratocaster", "Squier Affinity", "Gibson Les Paul Custom Shop", "Classica 1/4"], 0, "La Player II è il cuore della fascia media Fender.", "202901"], ["Qual è la prima domanda giusta per un intermedio?", ["\"Cosa ti manca nella chitarra che hai?\"", "\"Quanto vuoi spendere al massimo?\"", "\"Ti piace il rosso?\"", "\"Hai mai suonato?\""], 0, "Capire cosa non lo soddisfa ti dice cosa proporre.", null]]}, {"id": "u14l3", "t": "L'esperto", "cards": [["Chi è", "Suona da anni, spesso dal vivo, e sa cosa vuole. Cerca dettagli precisi: un preciso tipo di manico, pickup specifici, vernice alla nitro, costruzione USA, tutto massello. Non va convinto: va ascoltato.", []], ["Elettrica: 1.500 € e oltre", "Fender American Professional II e Ultra, Gibson Les Paul Standard e Custom, PRS Core, Gretsch Professional, Suhr, Music Man. Qui contano l'artigianalità, i materiali selezionati, il peso, il profilo del manico e la tradizione.", ["25476", "194941"]], ["Acustica e classica alta", "Martin D-28 e D-18 standard, Taylor 300-800, Furch, Lâg Master, Alhambra e Admira di fascia alta, chitarre da concerto. Contano il tutto massello, la qualità delle venature, l'incatenatura (bracing) e chi l'ha costruita.", ["199085"]], ["Come comportarsi", "Non spiegare le basi. Fai domande tecniche: \"Che profilo di manico preferisci? Che chitarra hai già? Cosa cerchi che non ha?\" Se non sai una cosa, dillo e informati: con l'esperto la sincerità vale più di tutto. Lascialo provare con calma e con l'ampli giusto.", []], ["L'esperto come cliente fedele", "Un esperto soddisfatto torna per ampli, pedali, setup e corde, e porta amici e allievi. È il cliente che costruisce la tua reputazione in negozio.", []]], "quiz": [["Con un chitarrista esperto, cosa NON devi fare?", ["Spiegargli le basi", "Ascoltarlo", "Fargli domande tecniche", "Lasciarlo provare"], 0, "L'esperto sa già le basi: vuole confrontarsi su dettagli e suono.", null], ["Se un esperto ti chiede una cosa che non sai?", ["Lo dici e ti informi", "Inventi", "Cambi discorso", "Lo ignori"], 0, "La sincerità costruisce fiducia, soprattutto con chi ne sa.", null], ["Quale di queste è una chitarra da esperto?", ["Fender American Professional II", "Yamaha Pacifica 012", "Squier Affinity", "Ibanez GIO"], 0, "La serie American Professional è prodotta negli USA, di fascia alta.", "25476"], ["Cosa cerca l'esperto in un'acustica alta?", ["Tutto massello, legni selezionati, bracing", "Il colore più acceso", "Il prezzo più basso", "Le corde in nylon"], 0, "A quel livello contano i materiali e la costruzione.", "199085"]]}]}, {"id": "u15", "t": "Vendere da professionista", "d": "Obiezioni, vendita completa e casi speciali", "c": "#F2584B", "lessons": [{"id": "u15l1", "t": "Rispondere alle obiezioni", "cards": [["\"Costa troppo\"", "Non abbassare subito il prezzo: chiedi \"Rispetto a cosa?\" Poi mostra un'alternativa più economica e spiega con onestà cosa cambia (tavola in massello, pickup, accordatura). Il cliente sceglie consapevole, e spesso torna sulla prima chitarra perché capisce il valore.", []], ["\"Online costa meno\"", "Rispondi con calma, senza parlare male di nessuno. Cosa ha in più il negozio: la prova dal vivo, la chitarra regolata prima di uscire, l'assistenza, una persona da chiamare se c'è un problema. Cavalli vende anche online, quindi chiedi al titolare come gestire i confronti di prezzo.", []], ["\"Ci devo pensare\"", "È normale. Chiedi con gentilezza: \"Cosa ti manca per decidere?\" Spesso è il budget, un dubbio tecnico o il parere di qualcuno. Rispondi a quello, dagli il tuo nome e il codice della chitarra, e invitalo a tornare a provarla.", []], ["\"Il mio maestro dice che…\"", "Il maestro è un tuo alleato, non un rivale. Rispondi così: \"Ottimo consiglio, vediamo insieme cosa ti ha detto\". Se puoi, proponi al cliente di chiamarlo o di portarlo in negozio.", []], ["\"È per mio figlio, non so se continuerà\"", "Proponi una chitarra economica ma suonabile, magari un kit. Spiega che una chitarra comoda aumenta la probabilità che il figlio continui. Ricorda che un genitore che si sente capito torna.", ["53581"]]], "quiz": [["Cliente: \"Costa troppo\". Qual è la prima risposta migliore?", ["\"Rispetto a cosa?\" e poi un'alternativa spiegata", "Abbassare subito il prezzo", "\"Allora vai via\"", "Ignorarlo"], 0, "Capire il confronto ti permette di spiegare il valore o proporre un'alternativa adatta.", null], ["Cliente: \"Online costa meno\". Cosa evidenzi?", ["Prova, regolazione, assistenza e una persona di riferimento", "Che i siti online sono truffe", "Che il prezzo è uguale anche se non lo è", "Niente"], 0, "Il valore del negozio fisico è il servizio: mai parlare male degli altri.", null], ["Cliente: \"Ci devo pensare\". Cosa chiedi?", ["\"Cosa ti manca per decidere?\"", "\"Quando torni, esattamente?\"", "\"Perché non compri adesso?\"", "Niente, lo saluti"], 0, "Scopri il dubbio vero e rispondi a quello.", null], ["Come tratti il \"maestro\" del cliente?", ["Come un alleato", "Come un rivale", "Lo critichi", "Lo ignori"], 0, "Il maestro può portare tanti allievi: averlo dalla tua parte è prezioso.", null]]}, {"id": "u15l2", "t": "La vendita completa e la consegna", "cards": [["Abbinamenti naturali", "A ogni chitarra corrispondono alcuni accessori che servono davvero: corde di scorta, borsa, accordatore, cavo e tracolla per l'elettrica; capotasto per chi canta; poggiapiede per la classica. Proporli è un servizio. Il cliente che arriva a casa senza cavo non è contento.", ["202642", "25430", "193930"]], ["Prima della consegna: controlla", "Accorda la chitarra. Controlla che le corde non frizzino e che siano a un'altezza comoda. Verifica che l'elettronica funzioni (tutti i pickup e i potenziometri, senza fruscii). Pulisci le impronte. Una chitarra che esce perfetta dal negozio è la tua firma.", []], ["Spiega in 2 minuti", "Come si accorda, ogni quanto cambiare le corde, come conservarla (lontana da termosifoni, auto e umidità), dove non toccare (truss rod, se non sa cosa fa). Dai il tuo nome: \"Per qualsiasi cosa chiedi di me\".", []], ["Dopo la vendita", "Invita il cliente a tornare per il cambio corde o per una regolazione: ripari chitarre, ed è un vantaggio enorme. Chiedi al titolare quali servizi offre il negozio dopo l'acquisto e presentali sempre allo stesso modo.", []]], "quiz": [["Cosa fai PRIMA di consegnare una chitarra?", ["Accordi, controlli l'altezza delle corde e l'elettronica, pulisci", "La metti in scatola subito", "Niente", "Cambi il colore"], 0, "Una chitarra perfetta in uscita è la tua firma come venditore e riparatore.", null], ["Quale accessorio è naturale con un'acustica per chi canta?", ["Capotasto mobile", "Wah", "Testata", "Poggiapiede"], 0, "Il capotasto adatta la tonalità alla voce.", "25246"], ["Cosa NON va consigliato per conservare la chitarra?", ["Lasciarla in macchina d'estate", "Tenerla nella borsa", "Lontana dai termosifoni", "Su un supporto"], 0, "Caldo e sbalzi di temperatura e umidità danneggiano legno, colle e vernice.", null], ["Perché invitare il cliente a tornare per il cambio corde?", ["Crea un rapporto e lui torna in negozio", "Per fargli perdere tempo", "Non serve", "Per obbligo di legge"], 0, "Il cliente che torna diventa fedele e compra anche il resto.", null]]}, {"id": "u15l3", "t": "Casi speciali", "cards": [["Il regalo", "Chiedi: per chi è (età, altezza), cosa ascolta, se suona già, se è mancino, il budget. Se non sa nulla, proponi un buono regalo o una chitarra facile da cambiare. Le persone mancine sono più di quante pensi, e Cavalli ha un reparto apposta.", []], ["Mancini", "Una chitarra mancina non è una normale chitarra girata: il manico, il ponte, l'elettronica e spesso il capotasto sono costruiti al contrario. Chiedi sempre \"Con che mano tieni il plettro?\" Se il cliente è mancino, mostra le mancine disponibili.", ["46117"]], ["Il cliente che vuole \"quel suono\"", "\"Voglio il suono di…\": chiedi l'artista e la canzone, e se puoi ascoltala insieme a lui. Poi componi il suono con chitarra, ampli, effetti e corde. Ricorda che spesso conta più l'ampli o il pedale che la chitarra.", ["199128"]], ["Il genitore che non sa niente", "Usa parole semplici, niente sigle. Fai al massimo tre domande (età, genere musicale, budget), proponi una sola soluzione completa e spiegala. La troppa scelta lo blocca.", ["53581"]]], "quiz": [["Per un regalo, quale domanda è fondamentale per non sbagliare?", ["Se chi la riceve è mancino", "Il segno zodiacale", "Il colore delle scarpe", "Che auto ha"], 0, "Regalare una destra a un mancino è un errore comune e facile da evitare.", null], ["Una chitarra mancina è…", ["Costruita al contrario in manico, ponte ed elettronica", "Una chitarra destra girata", "Una chitarra senza corde", "Una classica"], 0, "Non basta girare le corde: tutta la chitarra è speculare.", "46117"], ["Un genitore è confuso dalle troppe opzioni. Cosa fai?", ["Proponi una soluzione completa e la spieghi", "Gli mostri 20 chitarre", "Usi sigle tecniche", "Lo mandi online"], 0, "Poche domande e una proposta chiara rassicurano.", "53581"], ["Un cliente chiede \"il suono di Stevie Ray Vaughan\". Cosa proponi?", ["Strat, overdrive tipo Tube Screamer e ampli Fender", "7 corde con EMG", "Classica flamenca", "Ampli acustico"], 0, "SRV: Stratocaster, Tube Screamer e Fender pulito spinto.", "199128"]]}]}, {"id": "u16", "t": "Setup e cura", "d": "Regolare una chitarra e riconoscere i problemi comuni", "c": "#F2584B", "lessons": [{"id": "u16l1", "t": "Il setup in 6 passi", "cards": [["1. Corde nuove", "Si parte sempre da corde nuove, perché quelle vecchie falsano la regolazione. Pulisci la tastiera mentre sono smontate e controlla che i tasti non siano consumati.", ["193930", "29323"]], ["2. Truss rod (curvatura del manico)", "Il truss rod è un'asta di metallo dentro il manico che regola la curvatura. Se il manico è troppo curvo, le corde sono alte; se è troppo dritto, le corde frizzano. Si gira di un quarto di giro alla volta, con la chiave giusta. Non si forza mai.", ["171117", "52679"]], ["3. Altezza delle corde (action)", "Si regola al ponte: sellette sulle elettriche, osso sulle acustiche e sulle classiche. Più bassa vuol dire più comoda, ma se è troppo bassa le corde frizzano. Si misura al 12° tasto.", ["d:strat_front"]], ["4. Capotasto", "Se le corde sono troppo alte ai primi tasti, la chitarra è dura da suonare per i principianti. Se le cave del capotasto sono troppo profonde, la corda a vuoto frizza.", []], ["5. Intonazione", "Confronta la nota dell'armonico al 12° tasto con la stessa nota premuta al 12° tasto: devono essere uguali. Se la nota premuta è più alta, si allontana la selletta; se è più bassa, la si avvicina. Senza questa regolazione, la chitarra \"stona salendo\".", []], ["6. Altezza dei pickup", "I pickup troppo vicini alle corde distorcono e disturbano l'accordatura (sui single coil). Troppo lontani, suonano deboli. Si regolano con le viti del pickup finché il volume è bilanciato tra le corde.", ["38383"]]], "quiz": [["Qual è il primo passo di un setup?", ["Montare corde nuove", "Regolare i pickup", "L'intonazione", "Lucidare la paletta"], 0, "Corde vecchie falsano ogni misura.", "193930"], ["A cosa serve il truss rod?", ["A regolare la curvatura del manico", "A cambiare le corde", "A regolare il volume", "Ad alimentare i pedali"], 0, "Si gira di poco alla volta e mai forzando.", "171117"], ["La chitarra \"stona salendo\" sul manico. Cosa va regolato?", ["L'intonazione (sellette)", "La tracolla", "Il colore", "Il cavo"], 0, "Si confronta l'armonico al 12° tasto con la nota premuta.", null], ["Le corde frizzano su tutto il manico. Una possibile causa?", ["Manico troppo dritto o action troppo bassa", "Corde troppo nuove", "Plettro sbagliato", "Cavo lungo"], 0, "Poca curvatura o corde troppo basse fanno toccare i tasti.", null], ["Dove si misura l'altezza delle corde?", ["Al 12° tasto", "Al capotasto mobile", "Sulla paletta", "Sul jack"], 0, "Il 12° tasto è il punto di riferimento standard.", null]]}, {"id": "u16l2", "t": "Clima, problemi comuni e cura", "cards": [["Umidità: il nemico invisibile", "Il legno vive meglio con un'umidità del 45-55%. In inverno, con il riscaldamento, l'aria è secca: la tastiera si ritira, i bordi dei tasti sporgono e pungono, e sulle acustiche si possono aprire crepe sulla tavola. In estate, con troppa umidità, il manico si curva e le corde si alzano.", []], ["I problemi che vedrai di più", "Corde che frizzano: regolazione. Chitarra che non tiene l'accordatura: corde nuove non assestate, meccaniche o capotasto. Ronzio: cavo, massa o single coil vicino a fonti di disturbo. Potenziometri che gracchiano: sporcizia, si puliscono con lo spray per contatti. Jack che si allenta: si stringe il dado.", []], ["Diagnosi veloce davanti al cliente", "Fai domande: \"Da quando? Dopo un viaggio o un cambio di stagione? Hai cambiato le corde o la scalatura?\" Poi prova la chitarra con il cliente presente: capisce che stai lavorando seriamente e si fida.", []], ["Cura quotidiana", "Pulisci le corde e il manico dopo aver suonato, tieni la chitarra nella borsa o su un supporto lontano dai termosifoni, non lasciarla mai in auto e allenta un po' le corde se non la usi per mesi (non sulle elettriche usate spesso). Cambia le corde regolarmente.", ["28632", "48977"]]], "quiz": [["Qual è l'umidità ideale per una chitarra?", ["45-55%", "10-20%", "80-90%", "Non conta"], 0, "In questo intervallo il legno resta stabile.", null], ["In inverno i bordi dei tasti pungono le dita. Perché?", ["L'aria secca ha fatto ritirare la tastiera", "Le corde sono nuove", "Il cavo è rotto", "L'ampli è spento"], 0, "Il legno secco si restringe e i tasti restano della stessa larghezza.", null], ["Un potenziometro gracchia quando lo giri. Soluzione tipica?", ["Pulirlo con lo spray per contatti", "Cambiare la chitarra", "Mettere corde 13", "Alzare il gain"], 0, "Di solito è sporcizia: lo spray per contatti risolve.", null], ["Dove NON va mai lasciata una chitarra?", ["In auto", "Nella borsa", "Sul supporto", "In custodia"], 0, "Caldo e sbalzi di temperatura in auto possono rovinare colle, vernice e manico.", null]]}]}];
