window.DSRC={"d_front": "/martin-d28-street-legend-d28sl.html", "jackson": "/jackson-american-series-soloist-sl2-dx-lemon-ice-chitarra-elettrica-2802701820.html", "strat_front": "/fender-ltd-player-ii-stratocaster-rw-chitarra-elettrica-0141510572.html", "sg_front": "/gibson-sg-standard-61-stop-bar-pelham-blue-burst-sg6100pknh1.html", "lp_front": "/gibson-les-paul-standard-50s-figured-top-tobacco-burst-lps500tonh1.html", "tele_front": "/fender-player-ii-telecaster-chitarra-elettrica-rw-birch-green-0140550565.html", "es_front": "/gibson-es-335-figured-iced-tea-es35f00itnh1.html", "d_head": "/martin-d28-street-legend-d28sl.html", "es_body": "/gibson-es-335-figured-iced-tea-es35f00itnh1.html", "sg_body": "/gibson-sg-standard-61-stop-bar-pelham-blue-burst-sg6100pknh1.html", "taylor_front": "/taylor-314ce-next-generation-chitarra-acustica-elettrificata-314ce.html", "taylor_head": "/taylor-314ce-n-314cen.html", "cla_front": "/ramirez-estudio-140th-flamenco-cipresso-chitarra-classica-estudio140f.html", "flam_head": "/ramirez-estudio-140th-flamenco-cipresso-chitarra-classica-estudio140f.html", "strat_head": "/b-stock-chitarra-elettrica-fender-ltd-player-ii-stratocaster-rw-black-bstockf8.html", "wood_back": "/taylor-314ce-n-314cen.html", "strat_side": "/b-stock-chitarra-elettrica-fender-ltd-player-ii-stratocaster-rw-black-bstockf8.html", "tele_body": "/chitarra-elettrica-fender-american-professional-ii-telecaster-rw-olympic-white-con-custodia-0113940705.html", "rg_body": "/ibanez-rg550ca-chitarra-elettrica-crimson-red-rg550ca.html", "fretboard": "/taylor-314ce-n-314cen.html", "wood_top": "/taylor-314ce-n-314cen.html", "cla_head": "/chitarra-classica-ramirez-del-tiempo-abete-con-borsa-deltiempoa.html", "flam_front": "/ramirez-estudio-140th-flamenco-cipresso-chitarra-classica-estudio140f.html", "lp_body": "/gibson-les-paul-standard-60s-figured-top-blueberry-burst-con-custodia-lps600b9nh1.html", "lp_head": "/gibson-les-paul-standard-60s-figured-top-blueberry-burst-con-custodia-lps600b9nh1.html", "d_body": "/martin-d-18e-modern-deluxe-d18e.html", "strat_body": "/fender-70th-american-professional-ii-stratocaster-rw-comet-burst-con-custodia-0177000864.html", "floyd_lp": "/gibson-les-paul-axcess-standard-figured-floyd-rose-gloss-dc-rust-con-custodia-lpxs7dcrcf1.html", "gretsch": "/chitarra-semiacustica-gretsch-g5420t-electromatic-classic-orange-stain-2506115512.html", "rg_front": "/ibanez-rg550ca-chitarra-elettrica-crimson-red-rg550ca.html"};
window.SIMS=[["Mamma, 40 anni", "Mio figlio ha 9 anni e vuole imparare la chitarra a scuola di musica. Cosa prendo?", ["Una classica 3/4 con borsa, poggiapiede e accordatore", "Una Les Paul Standard", "Un'acustica jumbo 4/4", "Una 7 corde"], 0, "A scuola si parte quasi sempre con la classica, e a 9 anni la misura tipica è la 3/4. Componi subito il kit completo.", "34656"], ["Ragazzo, 16 anni", "Ascolto Metallica e Slipknot, ho 300 € in tutto. Mi serve anche l'ampli.", ["Jackson JS o Ibanez GIO più un piccolo ampli a modelli o Blackstar Debut", "Una Telecaster e nessun ampli", "Una classica", "Un Vox AC30 da solo"], 0, "Forma e pickup da metal, ampli con canale distorto e cuffie: nel budget e completo.", "173182"], ["Uomo, 35 anni", "Strimpello accordi e canto con gli amici. Voglio un'acustica che suoni piena, massimo 400 €.", ["Yamaha FG800 o FG820 (dreadnought, tavola in massello) più capotasto", "Una parlor piccola da studio", "Un'elettrica con distorsore", "Una flamenca"], 0, "La dreadnought ha bassi e volume per cantare. Il capotasto è l'accessorio naturale per chi canta.", "35873"], ["Chitarrista blues", "Ho una Strat e un ampli a transistor. Il suono mi sembra freddo e piatto.", ["Proporre un ampli a valvole o Tone Master, o un overdrive tipo Tube Screamer", "Cambiare subito chitarra", "Corde in nylon", "Un looper"], 0, "Il problema è quasi sempre l'ampli: un valvolare Fender o un Tube Screamer scaldano il suono.", "30346"], ["Cantautrice", "Suono nei locali con la mia acustica elettrificata. Ora mi collego all'ampli del bassista.", ["Proporre un ampli acustico con ingresso microfono (AER, Acus, Fender Acoustic)", "Un Marshall crunch", "Un pedale fuzz", "Una testata EVH"], 0, "L'ampli acustico riproduce tutto lo spettro e spesso ha l'ingresso per la voce.", "171665"], ["Studente, appartamento", "Vivo in un condominio, non posso fare rumore la sera.", ["Fender Mustang Micro o Boss Waza-Air, oppure un ampli con buona uscita cuffie", "Un Vox AC30", "Una cassa 4x12", "Un ampli da 100 W"], 0, "Per suonare in silenzio servono soluzioni pensate per le cuffie.", "197390"], ["Cliente indeciso", "La chitarra mi piace, ma online l'ho vista a 30 € in meno.", ["Ricordare con calma prova, regolazione, assistenza e garanzia in negozio, e chiedere al titolare come gestire il prezzo", "Dire che i siti online sono truffe", "Abbassare il prezzo da solo", "Dire che non è vero"], 0, "Il negozio vende servizio e fiducia. Le decisioni sul prezzo spettano al titolare.", null], ["Nonno", "Voglio regalare una chitarra a mio nipote, ma non so niente.", ["Chiedere età, se è mancino, cosa ascolta, e se suona già. In caso di dubbio, un buono regalo", "Vendere la più cara", "Dare la prima che capita", "Mandarlo online"], 0, "Poche domande evitano un regalo sbagliato. Il buono è la soluzione sicura.", null], ["Chitarrista esperto", "Cerco un'elettrica con manico avvitato, single coil e suono brillante, fascia alta.", ["Fender American Professional II Stratocaster", "Epiphone Les Paul", "Ibanez GIO", "Classica Alhambra"], 0, "Manico bolt-on, single coil e brillantezza sono il DNA Fender. In fascia alta: American Professional.", "25476"], ["Principiante, adulto", "Le corde mi fanno male alle dita e la chitarra è durissima.", ["Controllare il setup (action, capotasto) e proporre corde più leggere", "Dirgli di smettere", "Corde più grosse", "Un pedale distorsore"], 0, "Un buon setup e corde più leggere cambiano tutto. È anche un tuo servizio di riparazione.", "193930"], ["Rockettaro", "Ho una Les Paul e voglio il suono AC/DC, ho 500 € per l'ampli.", ["Un ampli in crunch britannico (Blackstar, Katana sul canale Brown o Crunch)", "Un ampli acustico", "Un Fender Champion pulito senza distorsione", "Un looper"], 0, "Humbucker più crunch britannico. In questo budget, Katana e Blackstar fanno bene il suono rock.", "195981"], ["Chitarrista mancino", "Sono mancino, ma tutti mi dicono di imparare con una chitarra destra.", ["Mostrare le mancine disponibili e lasciar decidere lui, provandole", "Insistere sulla destra", "Girare le corde di una destra", "Dire che le mancine non esistono"], 0, "Le mancine esistono e Cavalli ne ha un reparto: la scelta è del cliente.", "46117"], ["Ragazza, ascolta indie", "Mi piacciono i suoni sognanti, tipo riverberi enormi.", ["Un pedale riverbero (Boss RV-6 o Strymon BigSky) ed eventualmente un delay", "Un fuzz estremo", "Un accordatore", "Una 7 corde"], 0, "Riverbero e delay creano quell'atmosfera ampia.", "42786"], ["Papà", "Ha appena comprato la chitarra, cos'altro gli serve davvero?", ["Corde di scorta, borsa, accordatore e, per l'elettrica, cavo e tracolla", "Niente", "Una seconda chitarra", "Un amplificatore da concerto"], 0, "Gli accessori base rendono la chitarra subito usabile. Proporli è un servizio.", "25430"], ["Chitarrista con pedaliera", "Ho cinque pedali con le batterie e sento ronzii.", ["Proporre un'alimentazione per pedali (isolata per tanti pedali)", "Più batterie", "Un altro distorsore", "Un cavo più lungo"], 0, "Un'alimentazione corretta, a 9 V con negativo al centro e uscite isolate, riduce i ronzii ed elimina le batterie.", "30788"], ["Chitarrista jazz", "Cerco una chitarra per jazz e standard, suono caldo.", ["Una semiacustica o hollow body con humbucker al manico e corde più spesse", "Una superstrat a 24 tasti con Floyd", "Una classica flamenca", "Una Telecaster con fuzz"], 0, "Hollow body, humbucker al manico e ampli pulito sono il suono jazz.", "d:es_body"]];
